(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uz"] = {"ui":{"skip":"Mazmunga oʻtish","back":"← AI-gile’ga qaytish","lang.button":"Til: {name}","lang.dialog":"Tilni tanlang","lang.search":"Til qidirish","lang.none":"Mos til topilmadi","lang.notYet":"{name} hali tarjima qilinmagan","theme.aria":"Mavzuni almashtirish: yorugʻ, qorongʻi yoki qora","theme.toLight":"Yorugʻ mavzuga oʻtish","theme.toDark":"Qorongʻi mavzuga oʻtish","theme.toBlack":"Qora mavzuga oʻtish (haqiqiy qora, OLED ekranlar uchun qulay)","words.underline":"Sahifadagi bu soʻzlarning tagiga chizish","words.underlineHelp":"Maʼnosini koʻrish uchun nuqtali soʻz ustiga sichqonchani olib boring yoki unga bosing.","words.col.todo":"Hozircha tanlangan kartalar: jamoa keyingi navbatda shulardan boshlaydi.","words.col.doing":"Bir sun'iy intellekt hozir shu karta ustida ishlayapti.","words.col.review":"Bir sun'iy intellekt ishni tugatdi; sizga yetib borguncha boshqasi tekshiradi.","words.col.verify":"Sizni kutmoqda: sinab ko'ring va ishlayaptimi, ayting.","words.col.team":"Sizning eslatma yoki javoblaringiz, jamoa olishini kutmoqda.","words.col.done":"Tugallandi va qabul qilindi.","index.title":"AI-gile: sun’iy intellektli dasturchilar jamoangiz, bitta doskada","index.description":"AI-gile — sun’iy intellekt bilan kod yozadigan jamoalar uchun kanban doskasi. Siz uxlab yotganingizda ular ishlaydi; sizga esa qaror qilish, sinash va qabul qilish uchun bitta qisqa toʻplam qoladi.","hero.logoAlt":"AI-gile doskasi belgisi","hero.h1.html":"Sun’iy intellektli dasturchilar jamoangiz, bitta&nbsp;doskada.","hero.alpha":"🐣 Yopiq pre-alfa","hero.alphaTitle":"Hali erta va tugallanmagan: sinab koʻrganingiz uchun rahmat!","hero.lede":"Ular siz uxlayotganda ishlaydi. Ertalab sizni qisqa bir toʻplam kutadi: bir nechta savol, sinab koʻriladigan bir-ikki narsa, bitta-ikkita binafsha olmos. Bosing, qabul qiling, qahvangizga qayting.","dl.windows":"Windows ilovasi","dl.browser":"Brauzerda ishga tushirish","dl.messenger":"📱 Telefoningiz uchun Messenger","dl.soon":"Tez orada","dl.notify":"🔔 Ochilganda xabar bering","dl.notifySmall":"Alfa yoki beta","hero.secondary":"Agile, lekin jamoaga hech qachon stend-ap qahvasi kerak emas. (Baribir stend-ap oʻtkazishadi.)","pitch.h2":"AI-gile siz xohlagancha soʻzda","pitch.lede":"Uzunlikni tanlang: bir soʻzdan 144 gacha. Har bir uzunlik oʻz oʻlchamiga moslab yozilgan alohida tavsif. Sirpanchni suring yoki strelka tugmalaridan foydalaning.","pitch.rangeLabel":"Uzunlik soʻzlarda","pitch.dice":"🎲 boshqa variant","pitch.words.one":"{n} soʻz","pitch.words.other":"{n} soʻz","pitch.letters.one":"{n} harf","pitch.letters.other":"{n} harf","pitch.chars.one":"{n} belgi","pitch.chars.other":"{n} belgi","count.line.html.one":"Hozir doskada {n} karta bor","count.line.html.other":"Hozir doskada {n} karta bor","people.humans.html.one":"👥 {n} inson","people.humans.html.other":"👥 {n} inson","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} hozir ishda","people.working.html.other":"⚡ {n} hozir ishda","pre.title":"AI-gile: bu yerda nimadir qurilmoqda","pre.description":"Bu yerda nimadir qurilmoqda: sun’iy intellekt jamoalari siz soʻragan narsani quradigan va yoʻl-yoʻlakay sizga oʻrgatadigan doska. Hozircha doʻstlar bilan yopiq pre-alfa.","pre.h1":"Bu yerda nimadir qurilmoqda. 🤫","pre.line":"Sun’iy intellekt jamoalari siz soʻragan narsani quradigan va yoʻl-yoʻlakay sizga oʻrgatadigan doska. Hozircha doʻstlar bilan yopiq pre-alfa.","pre.btn":"🔔 Ochilganda xabar bering","pre.peek":"Oyna ortida: haqiqiy doska, jonli. Har bir karta – rangli chiziq.","pre.peekFake":"Oyna ortida: ishlayotgan doska shunday koʻrinadi.","pre.night":"🌙 Tungi qorovul boshqaryapti · 😴 inson dam olyapti","features.aria":"U nima qiladi","f.pile.h":"Siz uchun bitta toʻplam","f.pile.html":"<b>Siz uchun</b> barcha loyihalarda sizni kutayotgan hamma narsani yigʻadi: savollar, sinab koʻriladigan narsalar, faqat odam qila oladigan ishlar. Navbatingiz keyingisi nima ekanini va qancha vaqt olishini aytadi.","f.sleep.h":"Siz uxlaganingizda ishlaydigan jamoalar","f.sleep.p":"Har bir loyihaning rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Kartaga izoh yozing, jamoa uygʻonadi, ishni bajaradi va charchagan odam ham kuzata oladigan qadamlar bilan qaytaradi.","f.tester.h":"Avval sun’iy intellekt tekshiruvchisi koʻradi","f.tester.p":"Sizga biror narsa yetib kelmasidan oldin tekshiruvchi ilovaning nusxasida qadamlarni bajaradi va nimani koʻrganini skrinshot bilan koʻrsatadi. Oʻtganlarini varaqlab chiqing va bir bosishda qabul qiling.","f.proof.h":"Va’da emas, dalil","f.proof.p":"Har bir topshirish nima oʻzgarganini koʻrsatadi: fayllarni, farqni, skrinshotlarni. Tayyor boʻldimi, deb har bir ilovani ochib chiqish shart emas.","f.chat.h":"Rahbarlaringiz bilan suhbatlashing","f.chat.p":"Discord uslubidagi yon panel: har bir loyiha uchun bitta belgi, sizga kerak joyda binafsha olmoslar. Rahbarga gʻoyani yozing; u uni kartalar va rejaga aylantiradi, yonida ✅ Boshlash tugmasi bilan.","f.tidy.h":"Oʻzi tartibni saqlaydi","f.tidy.p":"Bogʻliq kartalar bittaga birlashadi, chalkash sarlavhalar tuzatiladi, token tekshiruvi esa kodni yengil saqlaydi. Almashtiriladigan narsa kam, oʻylanadigan narsa kam.","f.private.h":"Sizniki, sizning kompyuteringizda","f.private.li1":"Doska oʻz kompyuteringizda ishlaydi va faqat sizga javob beradi.","f.private.li2":"Odamlar orasidagi shaxsiy xabarlar boshidan oxirigacha shifrlangan.","f.private.li3":"Akkauntlar yoʻq, kuzatuvchilar yoʻq, kukilar yoʻq.","f.lang.h":"Oʻz tilingizda","f.lang.p":"Golland, uels va yapon tillaridan tortib qaroqchi, Yoda va klingon tillarigacha 120 dan ortiq til, kasbiy atamalar uchun inglizchaga tez qaytish tugmasi bilan.","f.service.h":"Gʻoyadan haqiqiy xizmatgacha","f.service.p":"AI bilan nimadir yaratdingizmi va undan endi odamlar foydalanyaptimi? Uni xizmat deb belgilang, doska uni yaxshi yuritishga yordam beradi: ishlashni tekshirish, ochiq holat sahifasi, tahlili yozilgan hodisalar, Go talab qiladigan oʻzgarishlar, har kuni tekshiriladigan zaxira nusxalar. Yordam har bir qadamni yoʻl-yoʻlakay oʻrgatadi.","msgr.h2":"AI-gile Messenger: jamoangiz choʻntagingizda","msgr.p1":"Doskani ochmasdan AI jamoangiz bilan gaplashing. Loyiha rahbarlaringiz va doʻstlaringiz bilan chatlashing, kartaning test qadamlarini koʻring va ularga javob bering, hammasi telefoningizdan.","msgr.p2":"Ulash uchun doskangizdagi QR kodni skanerlang. Birinchi martami? Samimiy demo chat sizga hammasini koʻrsatib beradi.","msgr.when":"Avval Android, keyin telefonlar va iPhone uchun veb-versiya.","msgr.who":"Loyiha rahbaringiz","msgr.b1":"Tungi rejim tuzatmasi tayyor. Test qadamlarini yuboraymi?","msgr.b2":"Ha, iltimos!","msgr.b3":"1. Sozlamalarni oching. 2. Tungi rejimni tanlang. Toʻgʻri koʻrinyaptimi?","tl.aria":"Birinchi suhbatdan yoʻl xaritasigacha boʻlgan vaqt chizigʻi","tl.h2":"Birinchi suhbatdan keyingi qadamgacha","tl.lede":"Haqiqiy sanalar va vaqtlar, oʻz vaqt mintaqangizda. Bugundan keyingisi — reja, sana va’da qilinmaydi.","tl.today":"Bugun","tl.planned":"rejalashtirilgan","tl.doing":"jarayonda","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Qoʻshiling","join.lede":"AI-gile’ni AuDHD bilan yashaydigan, ruhiy salomatlik bilan bir necha bor kurashgan soqolli bir gʻalati odam va juda koʻp sabrli agentlar yaratmoqda. Hozircha u yopiq, doʻstlar bilan yopiq alfada. Ochilganda sinab koʻrmoqchimisiz?","join.btn":"Qiziqishimni qayd etish","join.small":"Sizga email yozamiz, boshqa hech narsa yoʻq","footer.tag":"AI-gile. Kuzatuvchilarsiz, kukilarsiz, stend-ap qahvasiz.","footer.licence":"Biznes litsenziyasi","footer.status":"Holat","footer.privacy":"Nimalarni saqlaymiz","footer.thanks":"Qoʻngʻiroqlar ChilledChat tufayli","form.sending":"Yuborilmoqda…","form.failed":"Boʻlmadi: keyinroq qayta urinib koʻring.","form.offline":"AI-gile bilan aloqa oʻrnatib boʻlmadi: keyinroq qayta urinib koʻring.","form.keep":"Bundan faqat sizga javob berish uchun foydalanamiz, keyin oʻchirib tashlaymiz. Kuzatuvchilar yoʻq, kukilar yoʻq.","form.keepLink":"Nimalarni saqlaymiz","interest.title":"AI-gile: alfa ochilganda xabar bering","interest.description":"AI-gile’ning yopiq alfasi yoki betasi ochilganda xabar topish uchun emailingizni qoldiring.","interest.h1":"🔔 Ochilganda xabar bering","interest.lede":"AI-gile yopiq pre-alfada. Emailingizni qoldiring, sizga joy topilganda bir marta yozamiz.","interest.email":"Emailingiz","interest.which":"Qaysi sinov?","interest.alpha":"Yopiq alfa: erta, dagʻal, koʻp oʻzgarishlar","interest.beta":"Beta: barqarorroq, keyinroq","interest.both":"Qaysi biri avval chiqsa, farqi yoʻq","interest.submit":"Meni roʻyxatga yozing","interest.thanks":"Rahmat! Siz roʻyxatdasiz.","licence.title":"AI-gile: biznes litsenziyasi","licence.description":"AI-gile’dan biznesingizda foydalanasizmi? Bepul biznes litsenziyasiga ariza bering.","licence.h1":"📜 Biznes litsenziyasi","licence.lede":"AI-gile’dan ishda foydalanasizmi? Kimligingiz va nima bilan shugʻullanishingizni yozing. Agar bu biroz yaxshilik qilsa, litsenziya bepul.","licence.company":"Kompaniya","licence.website":"Veb-sayt","licence.what":"Nima bilan shugʻullanasiz","licence.how":"Bu dunyoga qanday yordam beradi","licence.email":"Email","licence.submit":"Ariza berish","licence.thanks":"Rahmat! Email orqali javob beramiz.","status.title":"AI-gile holati","status.h1":"AI-gile holati","status.quiet":"Hammasi tinch","status.intro":"AI-gile hozir ishlayaptimi? Bu sahifa har 5 daqiqada veb-sayt, doska ulashish, qoʻngʻiroqlar va yuklab olishni tekshiradi.","status.up":"Ishlayapti ({ms} ms da javob berdi)","status.slow":"Oxirgi tekshiruvga javob bermadi, qayta urinilmoqda","status.down":"Ishlamayapti: oxirgi ikki tekshiruvga javob bermadi","status.svc.web":"Veb-sayt","status.svc.web.offers":"Shu sayt: AI-gile nima ekanligi va qiziqish formasi","status.svc.boards":"Doska ulashish","status.svc.boards.offers":"Ommaviy doskalar, doʻstlar orasidagi xabarlar va taklifnomalar","status.svc.calls":"Qoʻngʻiroqlar","status.svc.calls.offers":"AI-gile ichida ovozli va video qoʻngʻiroqlar, ekranni ulashish","status.svc.download":"Yuklab olish","status.svc.download.offers":"Windows oʻrnatuvchisi va taklif havolalari","status.checking":"Tekshirilmoqda…","status.offline":"Holat xizmatiga hozir ulanib boʻlmayapti (qayta urinilmoqda)","status.updated":"yangilandi: {ago}","status.justNow":"hozirgina","status.min":"{n} daqiqa oldin","status.hours":"{n} soat oldin","status.days":"{n} kun oldin","privacy.title":"AI-gile: nimalarni saqlaymiz","privacy.h1":"Nimalarni saqlaymiz","privacy.lede":"Qisqasi: faqat siz yuborgan narsa, u ham uzoq vaqtga emas.","privacy.only":"Faqat siz bizga yuborgan narsa: formaga yozganingiz, masalan emailingiz. Siz haqingizda boshqa hech narsa.","privacy.sealed":"U muhrlanadi, shuning uchun serverimiz uni oʻqiy olmaydi: brauzeringizda, joʻnab ketishidan oldin (eskiroq brauzerda esa yetib kelgan zahoti). Uni faqat oʻzimizning doskamiz ocha oladi.","privacy.server":"Doskamizga yetib borishi bilan serverdan oʻchiriladi. 30 kundan keyin ham u yerda qolgan har qanday narsa baribir oʻchiriladi.","privacy.board":"Uni doskamizda faqat sizga javob berguncha saqlaymiz, keyin u yerdan ham oʻchiramiz.","privacy.none":"Kuzatuvchilar yoʻq, kukilar yoʻq, analitika yoʻq.","privacy.local":"Tilingiz va yorugʻ yoki qorongʻi mavzu tanlovingiz oʻz brauzeringizda qoladi. Ular hech qachon bizga yuborilmaydi.","privacy.ask":"Tezroq oʻchirilishini xohlaysizmi? Xatimizga javob yozib, shuni ayting.","live.h2":"Uning qurilishini jonli kuzating","live.caption":"Har bir karta yashirilgan: siz ishning shaklini ko'rasiz, so'zlarni emas.","live.watching.one":"jonli: {n} kuzatmoqda","live.watching.other":"jonli: {n} kuzatmoqda","live.last.now":"Oxirgi karta hozirgina koʻchirildi","live.last.min.one":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.min.other":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.hour.one":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.hour.other":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.day.one":"Oxirgi karta {n} kun oldin koʻchirildi","live.last.day.other":"Oxirgi karta {n} kun oldin koʻchirildi","live.offline":"Jonli taxta biroz dam olyapti. Tez orada yana kiring.","live.cols":"Backlog|Bajarilishi kerak|Jarayonda|Jamoa tekshirmoqda|Siz test qilishingiz kerak|Jamoa uchun|Bajarildi"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Topshirildi."]},{"n":2,"texts":["Robotlar kanbani.","Agentlar, tartibda.","Gʻoyalar, bajarildi."]},{"n":3,"texts":["Robotlar uchun kanban.","Gʻoyalar funksiyaga aylanadi.","Bepul agent kanbani."]},{"n":5,"texts":["Agentlar yuritadigan kanban doskasi.","Siz karta yozasiz. Agentlar quradi.","Bepul, mahalliy, sinalgan, biroz kulgili."]},{"n":8,"texts":["Sun’iy intellekt agentlari ishlaydigan bepul kanban doskasi.","Gʻoyani yozing. Agentlar quradi. Siz qabul qilasiz.","Bitta odam va koʻp sabrli robotlar uchun agile."]},{"n":13,"texts":["Kompyuteringizdagi kanban doskasi: kartalarni olib ishlaydiganlar esa sun’iy intellekt agentlari.","Gʻoya yozing. Agentlar jamoasi uni quradi. Tekshiruvchi esa sinab koʻradi.","Bepul, akkauntlarsiz, kuzatuvchilarsiz: bitta doska, bir nechta robot va hamma narsaga siz rahbar."]},{"n":21,"texts":["AI-gile — sun’iy intellekt dasturchi agentlari bilan ishlash uchun kanban doskasi. Kartalarni ular olib ishlaydi; siz esa ularni sinab koʻrasiz va qabul qilasiz.","Har bir loyihaning bitta rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Istalgan kartaga izoh yozing, jamoa darhol ishga kirishadi.","Oʻz kompyuteringizda ishlaydigan bepul va shaxsiy vazifalar doskasi. Ishlaydiganlar — robotlar. Oxirida «ha» deydigan esa faqat siz, hamma vaqt."]},{"n":34,"texts":["Siz gʻoyalarni doskaga qoʻyasiz. Sun’iy intellekt agentlaridan iborat jamoa ularni ishlaydigan funksiyalarga aylantiradi, sinab koʻradi va sinab koʻrish uchun qadamlar bilan sizga qaytaradi. Siz aytmaguningizcha hech narsa tayyor hisoblanmaydi.","AI-gile — Rich hozir oʻzi boshqaradigan agentlarning katta yordami bilan uyda yasagan kanban doskasi. U bepul, sizning kompyuteringizda ishlaydi va sotilmaydi, balki shunchaki doʻstlar bilan ulashiladi, hech kimdan pul soʻralmaydi.","Oddiy kanban doskasini tasavvur qiling: ustunlar Backlogdan Bajarildigacha, faqat kartalarni sun’iy intellekt agentlari olib ishlaydi. Ular yutuqlar haqida xabar beradi, tiqilib qolsa soʻraydi va doimo sizning roziligingizni kutadi."]},{"n":55,"texts":["AI-gile — jamoasi sun’iy intellekt agentlaridan iborat kanban doskasi. Har bir loyihada ishni rejalashtiradigan rahbar va uni bajaradigan yordamchilar bor. Funksiya tayyor boʻlganda sun’iy intellekt tekshiruvchisi uni sinab koʻradi va skrinshot oladi, keyin u sizning toʻplamingizga tushadi. Qabul qiling yoki izoh yozing, ular qayta ishlaydi.","Bu bir kishi bir vaqtda koʻplab sun’iy intellekt kod yozish seanslarini kuzatib borish yoʻli sifatida boshlandi va chinakam doskaga aylandi. U sizning kompyuteringizda ishlaydi, akkaunt talab qilmaydi va kuzatuvchilari yoʻq. Doʻstlar va qiziquvchilar uchun bepul. U hali tugallanmagan ham, shuning uchun dagʻalliklar va goho kutilmagan holatlarni kuting.","Mana, halol variant. Gʻoyalarni baribir siz oʻylab topasiz, natijalarni ham baribir siz tekshirasiz. AI-gile esa oraliqdagi hamma narsani qiladi: kartalarni tartibda saqlaydi, siz izoh yozganingizda kerakli agentni uygʻotadi, aynan nima oʻzgarganini koʻrsatadi va hammasini faqat siz uchun bitta qisqa toʻplamga yigʻadi. Boshqa hech narsa shart emas."]},{"n":89,"texts":["AI-gile — oʻz kompyuteringizda ishga tushiradigan bepul kanban doskasi. Har bir loyihada odamlar oʻrniga sun’iy intellekt agentlaridan iborat jamoa bor: gʻoyalaringizni kartalar va rejaga aylantiradigan rahbar hamda kartalarni ustuvorlik tartibida oladigan yordamchilar. Biror narsa qurib boʻlinganda sun’iy intellekt tekshiruvchisi sinov qadamlarini bajaradi va nimani koʻrganini sizga koʻrsatadi. Keyin u «Siz uchun» deb nomlangan bitta toʻplamda kutadi. Siz qabul qilasiz yoki izoh yozasiz, jamoa esa yana urinib koʻradi. Siz boʻlmasangiz, hech narsa «Bajarildi»ga yetmaydi.","Kutilmagan ba’zi imkoniyatlar ham bor. Tungi qorovul siz uxlaganingizda «Bajarilishi kerak» ustunini toʻldirib turadi va sizdan javob talab qilmaydigan kartalarni tanlaydi. Token hisoblagichi agentlar bugun va shu hafta qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa ularga sarflashni toʻxtatishni buyuradi. Doʻstlaringizga xabar yozishingiz mumkin, shaxsiy xabarlar esa boshidan oxirigacha shifrlangan. Doska taxminan 120 tilda gapiradi, jumladan golland, flamand, qaroqchi va klingon tillarida. Bularning hech biri bir tiyin turmaydi, hech kim sizga biror narsa sotmoqchi ham emas.","AI-gile — kichik, shaxsiy loyiha, kompaniya emas. Rich bir nechta sun’iy intellektli kod loyihasini har bir ilovani alohida ochmasdan kuzatib borishni xohladi, shuning uchun agentlar bilan birga buning uchun doska yasadi, keyin esa qolgan qismini ham oʻsha doska bilan qurdi. U hozir yopiq pre-alfada, ya’ni bir hovuch doʻstlar uchun asosan ishlaydi. Narxlar sahifasi yoʻq, axborot byulleteni yoʻq, oʻsish rejasi ham yoʻq. Agar bularning hammasi foydali tuyulsa, u bir oz kengroq ochilganda sinab koʻrishni soʻrashingiz mumkin."]},{"n":144,"texts":["AI-gile — bitta odam va koʻplab sun’iy intellekt agentlari uchun kanban doskasi. U oʻz kompyuteringizda ishlaydi va butunlay bepul. Siz loyihalar qoʻshasiz, har bir loyiha esa oʻz rahbari va kichik jamoasini oladi. Rahbar bilan Discord’dagiga oʻxshab suhbatlashasiz va gʻoyani tasvirlab berasiz; rahbar uni kartalar va rejaga aylantiradi, keyin «Boshlash» tugmasini bosishingizni kutadi. Jamoa kartalarni ustuvorlik tartibida birma-bir ishlab chiqadi, buning uchun til modellari uchun yasalgan oddiy buyruq qatoridan foydalanadi. Biror narsa sizga qaytishidan oldin sun’iy intellekt tekshiruvchisi ilovaning nusxasida barcha qadamlarni bajaradi va skrinshot biriktiradi. Tayyor ish oʻzgargan fayllar va farq bilan sizning toʻplamingizga tushadi. Siz uni qabul qilasiz yoki izoh qoldirasiz, jamoa esa uygʻonib, qayta urinib koʻradi. Kartani «Bajarildi» ustuniga faqat siz va faqat oʻzingiz koʻchira olasiz.","AI-gile bilan taxminan bir kun shunday oʻtadi. Kechqurun bir nechta izoh qoldirasiz: bu tugma notoʻgʻri joyda turibdi, u roʻyxatni saralash kerak, qorongʻi mavzu boʻlsa-chi. Siz uxlashga ketasiz. Agentlar izohlarni oʻqiydi, oʻzgartirishlarni qiladi, hammasini sinab koʻradi va sizga qaytaradi. «Bajarilishi kerak» boʻshab qolsa, tungi qorovul uni backlogdan sizdan javob talab qilmaydigan kartalar bilan toʻldiradi. Ertalab bitta qisqa toʻplam kutadi: bir nechta savol va sinab koʻriladigan bir nechta narsa, har biri uyqusirab turgan odam ham bajara oladigan qadamlar va ishlayotganini koʻrsatadigan skrinshot bilan. Siz birma-bir bosib chiqasiz, yaxshilarini qabul qilasiz, qolganlarini qaytarasiz. Token hisoblagichi bularning hammasi qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa tejamkor haftalar uchun tayyor turadi. Keyin nonushta qilasiz, bunda agentlar hozircha afsuski yordam bera olmaydi.","Avval AI-gile nima emasligi haqida. U startap emas, sotuvga qoʻyilmagan va hech kim maʼlumotlaringizni yigʻmaydi. U kompyuteringizda ishlaydigan, akkauntsiz, kuzatuvchisiz va kukisiz bepul doska. U nima esa: barcha sun’iy intellektli kod loyihalarini bir vaqtda koʻrish uchun yagona saranjom joy, bunda kartalarni agentlar jamoasi bajaradi, qarorlarni esa siz qabul qilasiz. U bogʻliq kartalarni birlashtiradi, chalkash sarlavhalarni tuzatadi va kod qanchalik yengil qolayotganini kuzatib turadi. U taxminan 120 tilda gapiradi, golland va flamand tillaridan tortib qaroqchi va klingon tillarigacha. Doʻstlar bir-biriga shaxsiy va shifrlangan xabar yozishi mumkin. Uni Rich va juda koʻp sabrli agentlar yaratdi, asosan oʻzidan oʻzi foydalanib. U hozir yopiq pre-alfada, shuning uchun ba’zi joylari dagʻal. Qiziq tuyulsa, yaxshilab soʻrang, balki boshqalardan erta kirib qolarsiz."]}],"quips":{"1":"Bitta soʻz. Jasur. Balki juda jasur.","3":"Uchta soʻz. Allaqachon koʻp mahsulot sahifalaridan halolroq.","8":"Sakkizta soʻz. Baribir bitta stend-apdan qisqa.","21":"Aytgancha, uzunliklar story point’lar. Albatta-da.","55":"Ellik beshta soʻz. Siz oʻqiguncha ikkita karta tugadi.","144":"Bu eng uzuni. 233 yoʻq. Agentlar uxlashga ketdi."}},"timeline":{"first-idea.name":"Birinchi gʻoya","first-idea.line":"Hali bitta qator kod boʻlmagan paytdagi eng birinchi suhbat.","first-board.name":"Birinchi doska","first-board.line":"Oʻz yaratilishini kuzatib boradigan doska: kartalar, ustunlar, sudrab tashlash, loyihalar.","team-roles.name":"Jamoa va rollar","team-roles.line":"Agent profillari, jamoa shablonlari, maydonlar va kim nima qilishi.","install.name":"Oʻrnatish va relizlar","install.line":"Doʻst oʻrnata oladigan zip, oʻz-oʻzidan yangilanish, kanallar va ortga qaytarish.","usage-saver.name":"Sarfni tejash","usage-saver.line":"Ishga tushirishlar narxini oʻlchash, kodni yengil saqlash, limitingizni asrash.","friends.name":"Doʻstlar va ulashish","friends.line":"Shaxsiy xabarlar, aralashtirilgan uzatgich, takliflar, rollar va umumiy loyihalar.","languages.name":"Tillar","languages.line":"Ekrandagi har bir matn til faylida, avval golland va flamand tillari.","ai-tester.name":"Sun’iy intellekt tekshiruvchisi","ai-tester.line":"Tekshiruvchi har bir topshirishni avval koʻrib chiqadi va nimani koʻrganini koʻrsatadi.","website.name":"Veb-sayt","website.line":"aigile.lol, tizer va shu vaqt chizigʻi.","streaming.name":"Chat va strimlar","streaming.line":"Discord, Twitch, OBS, strimer rejimi, GIFlar va emojilar.","no-ai.name":"Sun’iy intellektsiz nashr","no-ai.line":"Sun’iy intellektsiz kod yozadiganlar uchun doska va ochiq doskalar.","night-watch.name":"Tungi qorovul","night-watch.line":"Qorovul va Scrum Master siz uxlaganingizda jamoalarni ish ustida ushlab turadi.","p-more.name":"Qolgan hamma narsa","p-more.line":"Navbatini kutayotgan kichikroq gʻoyalar.","p-android.name":"Telefon va Android","p-android.line":"Doskangizga telefondan kirish, keyin esa mahalliy Android ilovasi.","p-release.name":"Alfa va undan keyin","p-release.line":"Yopiq alfa, jonli sayt, keyin beta.","p-languages.name":"Koʻproq tillar","p-languages.line":"130 ta til va oʻrganuvchilar uchun tilga shoʻngʻish rejimi.","p-engines.name":"Koʻproq sun’iy intellekt dvigatellari","p-engines.line":"Har bir agent uchun Claude, Codex, Gemini, Copilot yoki Cursor ni tanlang.","p-pro.name":"Professional amaliyot","p-pro.line":"Xavf belgilari, birlashtirish eshiklari, hodisa kartalari va toʻsiqlar.","p-self.name":"Sizga gʻamxoʻrlik","p-self.line":"Charchoq rejimi, oʻzingizga qarash eslatmalari va 4:20.","p-servers.name":"Serverlar va kengayish","p-servers.line":"Umumiy server sozlamalari, rollar va oʻsishni rejalashtirish.","p-livestream.name":"Strim qoʻshimchalari","p-livestream.line":"Twitch chati, shaxsiy emojilar va ochiq jonli koʻrinish."},"words":{"button":"📖 Kasbiy atamalar","h":"📖 Soʻzlar izohi","intro":"Oddiy tilda bepul oʻqitish: birinchi gʻoyadan odamlar tayanadigan xizmatgacha uchraydigan har bir soʻz, yoʻl-yoʻlakay Agile, qurish, xavfsiz saqlash va AI bilan ishlash.","search":"Soʻz qidirish…","none":"Bunday soʻz yoʻq.","close":"Yopish","count":{"one":"{count} ta soʻz","other":"{count} ta soʻz"},"groups":[{"id":"idea","name":"💡 Gʻoya va oʻrganish"},{"id":"plan","name":"🗺️ Ishni rejalashtirish"},{"id":"agile","name":"🔁 Agile ish usullari"},{"id":"build","name":"🛠️ Yaratish"},{"id":"test","name":"🧪 Sinov va sifat"},{"id":"change","name":"🔀 Xavfsiz oʻzgartirish"},{"id":"run","name":"🛎️ Xizmatni yuritish"},{"id":"sec","name":"🔒 Xavfsizlik va maxfiylik"},{"id":"ai","name":"🤖 AI bilan ishlash"},{"id":"money","name":"💰 Pul va litsenziyalar"}],"list":[{"id":"discovery","g":"idea","word":"Kashfiyot","text":"Hali hech narsa qurilmasidan oldin, qaysi muammoni kim uchun hal qilishga arzishini aniqlaydigan dastlabki bosqich.","also":["kashfiyot bosqichi","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Muammo bayoni","text":"Kimda qanday muammo borligini va nega muhimligini aytadigan bir-ikki gap, toki hamma bir maqsadga qarasin.","also":["muammo bayonlari","problem statements"]},{"id":"user","g":"idea","word":"Foydalanuvchi","text":"Siz yaratgan narsadan foydalanadigan odam. Ish aynan uning ehtiyojlari uchun qilinadi.","also":["foydalanuvchilar","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Manfaatdor tomon","text":"Ish natijasi qiziqtiradigan yoki unga taʼsir qiladigan har kim, masalan buning uchun pul toʻlayotgan, undan foydalanayotgan yoki uni qoʻllab-quvvatlayotgan odamlar.","also":["manfaatdor tomonlar","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Foydalanuvchilarning bir turini ifodalaydigan oʻylab topilgan, lekin hayotiy odam; jamoa «Sam buni oson deb topadimi?» deb soʻray olishi uchun.","also":["personalar","personas"]},{"id":"userresearch","g":"idea","word":"Foydalanuvchi tadqiqoti","text":"Taxmin qilib oʻtirmay, haqiqiy odamlar bilan gaplashib va ularni kuzatib, nimaga muhtojligini bilib olish.","also":["foydalanuvchilar bilan suhbat","user interviews"]},{"id":"journey","g":"idea","word":"Foydalanuvchi yoʻli","text":"Odam biror ishni bitirish uchun bosib oʻtadigan qadamlar: u haqida birinchi eshitganidan tugatgunicha, mahsulotingizdan tashqarida ham. Uni chizib chiqsangiz, qayerda qiynalayotgani koʻrinadi.","also":["foydalanuvchi yoʻllari","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Ogʻriqli nuqta","text":"Bugun odamlarni bezovta qiladigan yoki sekinlashtiradigan narsa. Yaxshi mahsulotlar ogʻriqli nuqtalarni yoʻqotadi.","also":["ogʻriqli nuqtalar","pain points"]},{"id":"assumption","g":"idea","word":"Faraz","text":"Ishonadigan, lekin hali tekshirmagan narsangiz. Farazlarni yozib qoʻysangiz, avval nimani sinash kerakligi koʻrinadi.","also":["farazlar","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Gipoteza","text":"Tekshirmoqchi boʻlgan eng yaxshi taxminingiz va nima boʻlishini kutayotganingiz, masalan «birinchi oy bepul boʻlsa, odamlar roʻyxatdan oʻtadi».","also":["gipotezalar","hypotheses"]},{"id":"experiment","g":"idea","word":"Tajriba","text":"Gʻoyaga koʻp vaqt va pul tikishdan oldin, u ishlashini bilish uchun oʻtkaziladigan kichik, rejalashtirilgan sinov.","also":["tajribalar","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Konsept isboti (PoC)","text":"Gʻoya umuman ishlay oladimi, shuni koʻrish uchun tez va qoʻpol urinish. Javobni olgach, odatda tashlab yuboriladi.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Mahsulotning dastlabki modeli, koʻpincha bosiladigan rasmlar; uni toʻgʻri qurishdan oldin gʻoyani odamlarda sinab koʻrish uchun.","also":["prototiplar","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Ekranning oddiy eskizi: narsalar qayerda turishini koʻrsatadi, ranglarsiz va haqiqiy mazmunsiz.","also":["wireframes","vayrfreym"]},{"id":"mockup","g":"idea","word":"Maket (mockup)","text":"Ekran qanday koʻrinishini haqiqiy ranglar va matn bilan koʻrsatadigan batafsil rasm, lekin hali hech narsa ishlamaydi.","also":["maketlar","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Biznes-asoslash (business case)","text":"Loyihani nega qilish kerakligining sabablari: u qancha turadi, nima keltiradi yoki tejaydi va xavflari qanday.","also":["biznes asoslar","business cases"]},{"id":"feasibility","g":"idea","word":"Amalga oshirish mumkinligi","text":"Qoʻlingizdagi vaqt, pul va mahorat bilan biror narsani haqiqatan qurish va keyin qoʻllab-quvvatlab turish mumkinmi, shu masala."},{"id":"outcome","g":"idea","word":"Natija","text":"Odamlar uchun istagan oʻzgarishingiz, masalan qoldirilgan uchrashuvlar kamayishi. U qancha narsa qurilganidan muhimroq.","also":["natijalar","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Yaratilgan narsa (output)","text":"Jamoa yaratgan narsa, masalan yangi ekran yoki hisobot. Uni yaratish avtomatik ravishda kimgadir foyda berishini bildirmaydi.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Muvaffaqiyat oʻlchovi","text":"Ish maqsadiga erishgan-erishmaganini koʻrsatadigan raqam, masalan buyurtmasini oxirigacha bajarayotganlar sonining oshishi.","also":["muvaffaqiyat oʻlchovlari","success metrics"]},{"id":"kpi","g":"idea","word":"Asosiy samaradorlik koʻrsatkichi (KPI)","text":"Ishlar yaxshi ketayotganini bilish uchun kuzatadigan muhim raqam, masalan haftasiga roʻyxatdan oʻtganlar soni.","also":["KPI","KPIlar","key performance indicator"]},{"id":"okr","g":"idea","word":"Maqsadlar va asosiy natijalar (OKR)","text":"Maqsad qoʻyish usuli: maqsad nimani xohlashingizni aytadi, bir necha asosiy natija esa unga yetganingizni koʻrsatadigan raqamlardir.","also":["OKR","OKRlar"]},{"id":"product","g":"plan","word":"Mahsulot","text":"Foydalanuvchilari uchun qurilayotgan va qoʻllab-quvvatlanayotgan narsa, masalan ilova, veb-sayt yoki vosita.","also":["mahsulotlar","products"],"noTip":1},{"id":"vision","g":"plan","word":"Mahsulot viziyasi","text":"Mahsulot kimga yordam berishi va uzoq muddatda qayoqqa ketayotgani haqida qisqa bayon.","also":["viziya bayoni","vision statement"]},{"id":"po","g":"plan","word":"Mahsulot egasi (PO)","text":"Nima qurilishi va qaysi tartibda ekanini hal qiladigan odam, shunda jamoa doim eng muhim ish ustida ishlaydi. AI-gileʼda bu siz.","also":["PO","mahsulot egalari","product owners"]},{"id":"pm","g":"plan","word":"Mahsulot menejeri (PM)","text":"Mahsulot yoʻnalishiga qaraydigan odam: u qaysi muammolarni, kim uchun va nega hal qiladi. PM loyiha menejerini ham anglatishi mumkin, shuning uchun qaysi ekanini tekshiring.","also":["mahsulot menejerlari","product managers"]},{"id":"projmgr","g":"plan","word":"Loyiha menejeri","text":"Loyihani vaqtida va byudjet doirasida ushlab turadigan, kim nima qilishi va qachongacha ekanini kuzatadigan odam.","also":["loyiha menejerlari","project managers"]},{"id":"roadmap","g":"plan","word":"Yoʻl xaritasi","text":"Keyingi oylarda nima kelishining tartibli, taxminiy rejasi. U aniq sanalarni emas, yoʻnalishni koʻrsatadi va oʻrgangan sari oʻzgaradi.","also":["yoʻl xaritalari","roadmaps"]},{"id":"milestone","g":"plan","word":"Muhim bosqich","text":"Loyihada belgilab qoʻyishga arziydigan nuqta, masalan «birinchi versiya ishga tushdi» yoki «100 foydalanuvchi».","also":["muhim bosqichlar","milestones"]},{"id":"mvp","g":"plan","word":"Minimal hayotiy mahsulot (MVP)","text":"Haqiqiy odamlarga hali ham foydali boʻlgan mahsulotning eng kichik versiyasi, shunda ulardan erta oʻrganasiz.","also":["MVP","MVPlar","minimum viable product"]},{"id":"requirement","g":"plan","word":"Talab","text":"Tayyor mahsulot qilishi yoki boʻlishi shart boʻlgan narsa.","also":["talablar","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Qamrov","text":"Ishga nimalar kiradi va xuddi shunday muhimi, nimalar kirmaydi.","also":["qamrovda","qamrovdan tashqarida","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Qamrovning oʻsib ketishi","text":"Ishga asta-sekin tobora koʻproq narsa qoʻshilib, qoʻshimcha vaqt yoki xarajat haqida hech kim kelishmagani uchun u hech tugamay qolishi.","also":["feature creep","imkoniyatlarning oʻsib ketishi"]},{"id":"feature","g":"plan","word":"Imkoniyat (feature)","text":"Mahsulot odamlar uchun qila oladigan bitta narsa, masalan «parolni tiklash».","also":["imkoniyatlar","funksiya","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epik","text":"Bir yoʻla bajarib boʻlmaydigan katta ish boʻlagi, shuning uchun u kichikroq kartalarga boʻlinadi.","also":["epiklar","epics"]},{"id":"story","g":"plan","word":"Foydalanuvchi hikoyasi","text":"Foydalanuvchi nuqtai nazaridan yozilgan kichik ish boʻlagi: «Xaridor sifatida savatimni saqlab qoʻymoqchiman, toki xaridni keyinroq yakunlay olay.» U nima qurish kerakligi haqida suhbat boshlaydi.","also":["foydalanuvchi hikoyalari","user stories"]},{"id":"ac","g":"plan","word":"Qabul mezonlari (AC)","text":"Bitta karta bajarilgan hisoblanishi uchun oʻtishi kerak boʻlgan tekshiruvlar; ish boshlanmasidan oldin kelishiladi, masalan «chiqib qaytadan kirganimda savat joyida turibdi».","also":["qabul mezonlari","acceptance criteria"]},{"id":"task","g":"plan","word":"Vazifa","text":"Bajarilishi kerak boʻlgan bitta ish, koʻpincha kattaroq hikoyaning bir kichik qadami.","also":["vazifalar","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket","text":"Kartaning boshqa nomi: boshidan oxirigacha kuzatiladigan bitta ish yoki bitta soʻrov.","also":["tiketlar","tickets"]},{"id":"priority","g":"plan","word":"Ustuvorlik","text":"Boshqa hamma narsaga nisbatan qanchalik muhim yoki shoshilinch ekani, shunda eng muhim ish birinchi bajariladi.","also":["ustuvorliklar","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Ustuvorlashtirish","text":"Ishni muhimlik tartibida joylashtirish. Keng tarqalgan usul MoSCoW: Must have (shart), Should have (kerak), Could have (boʻlsa yaxshi), Won’t have (bu safar emas).","also":["ustuvorlash","MoSCoW"]},{"id":"estimate","g":"plan","word":"Taxminiy baho","text":"Ish boʻlagi qanchalik katta yoki uzoq davom etishiga eng yaxshi taxmin. Bu vaʼda emas, taxmin.","also":["taxminiy baholar","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Hikoya ballari (story points)","text":"Ish hajmini soatlarda emas, kartalarni bir-biri bilan solishtirib («bunikidan taxminan ikki baravar katta») taxmin qilish usuli. Ular jamoalarni bir-biri bilan solishtirish uchun emas.","also":["story point","hikoya ballari"]},{"id":"tshirt","g":"plan","word":"Futbolka oʻlchamlari (T-shirt sizing)","text":"Ish hajmini S, M, L yoki XL deb taxmin qilish. Tez va dastlabki rejalashtirish uchun yetarli.","also":["t-shirt sizes","futbolka oʻlchamlari"]},{"id":"poker","g":"plan","word":"Rejalashtirish pokeri (Planning poker)","text":"Baholash oʻyini: hamma bir vaqtda oʻz hajm kartasini koʻrsatadi, keyin eng yuqori va eng past baho egalari sababini tushuntiradi.","also":["Scrum poker","Scrum pokeri"]},{"id":"dependency","g":"plan","word":"Bogʻliqlik","text":"Bir ish boshqasi tugamaguncha boshlana olmaydigan yoki tugay olmaydigan holat.","also":["bogʻliqliklar","dependencies"]},{"id":"blocker","g":"plan","word":"Toʻsiq (blocker)","text":"Ishning hozir oldinga siljishiga xalaqit beradigan har qanday narsa, masalan javobning yoʻqligi yoki buzilgan vosita.","also":["toʻsiqlar","blockers"]},{"id":"deadline","g":"plan","word":"Muddat (deadline)","text":"Biror ish tugatilishi shart boʻlgan sana.","also":["muddatlar","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Topshiriladigan natija","text":"Ish yaratib, topshiradigan aniq narsa, masalan ishlaydigan sahifa yoki hisobot.","also":["deliverables","topshiriladigan natijalar"]},{"id":"forecast","g":"plan","word":"Prognoz","text":"Hozirgacha bilganingizga qarab, nima boʻlishi mumkinligi haqidagi bashorat, masalan ish qachon tugashi.","also":["prognozlar","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Koʻrsatkich (metrika)","text":"Vaqt oʻtishi bilan oʻlchab, kuzatib boriladigan har qanday narsa, masalan sahifaga tashriflar yoki xatoni tuzatish qancha vaqt olishi.","also":["koʻrsatkichlar","metrics"]},{"id":"feedback","g":"plan","word":"Fikr-mulohaza","text":"Odamlarning ishingiz haqida aytgan gaplari, yaxshisi ham, yomoni ham. Uni erta va tez-tez olish Agileʼning yuragi.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Hali rejaga kiritilmagan gʻoya va ishlar kutish roʻyxati, eng muhimi tepada. «Bajarilishi kerak»ka oʻtmaguncha, u yerdagi hech narsa ustida ish boshlanmaydi."},{"id":"sprint","g":"agile","word":"Sprint","text":"Maqsadi va tugatilishi kerak boʻlgan kelishilgan kartalar toʻplami bor qisqa, aniq ish davri (koʻpincha bir-ikki hafta, hech qachon bir oydan oshmaydi).","also":["sprintlar"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Qisqa kundalik uchrashuv: har bir jamoa aʼzosi nima qildi, keyin nima qiladi va unga nima xalaqit beryapti. Scrumʼda u kundalik scrum deb ataladi.","also":["standup","stand-ups","daily scrum","daily stand-up","kundalik scrum"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Kartalar doska ustunlari (masalan Bajarilishi kerak, Jarayonda, Bajarildi) boʻylab harakatlanadigan va jamoa bir vaqtda jarayondagi ishni cheklaydigan ish usuli, shunda ish toʻxtovsiz oqadi."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP — work in progress (jarayondagi ish) qisqartmasi. WIP limiti — ustun bir vaqtda ushlab turishi kerak boʻlgan eng koʻp karta soni, shunda jamoa koʻproq narsa boshlashdan oldin boshlaganini tugatadi.","also":["WIP"]},{"id":"dod","g":"agile","word":"Bajarildi taʼrifi","text":"Jamoaning «tayyor» nimani anglatishi haqidagi qisqa roʻyxati, masalan, test qilingan va tushuntirilgan, karta sizga topshirilishidan oldin. Uning egizagi, Tayyor taʼrifi, karta boshlash uchun yetarlicha aniq boʻlganini aytadi.","also":["Definition of Ready","DoD","DoR","tayyorlik taʼrifi"]},{"id":"retro","g":"agile","word":"Retro","text":"Jamoa qanday ishlayotganiga muntazam nazar tashlash va keyingi safar yaxshiroq qilish uchun bir-ikki narsa haqida kelishish. Retrospective soʻzining qisqartmasi. AI-gileʼda retro jamoaning ish usullariga oʻzgarish taklif qiladi, siz esa Go yoki «Hali emas» deysiz.","also":["retrolar","retrospektiva","retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Toʻda","text":"Hamma bir joyga: koʻp odam boshqa ishlarini qoldirib, bitta shoshilinch masalani hal boʻlguncha birga tuzatadi. AI-gileʼda barcha jamoalar bitta loyihaga yordam beradi, boshqa loyihalar esa shu orada kutib turadi.","also":["toʻda boʻlib","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrumʼda jamoaga yaxshi ishlashga yordam beradigan odam: ularga xalaqit beradigan narsalarni olib tashlaydi, uchrashuvlarni izda ushlaydi va yaxshi odatlarni oʻrgatadi, hech kimga buyruq bermasdan. AI-gileʼda Lead Scrum Master tiqilib qolgan kartalarni topadi, jamoalarni turtadi va barcha loyihalar boʻylab nima kutayotganini eslatib turadi.","also":["Lead Scrum Master","skram-master"]},{"id":"agile","g":"agile","word":"Agile","text":"Kichik qadamlarda ishlash usuli: ozgina quriladi, haqiqiy natijalar tez-tez koʻrsatiladi, odamlar aytganidan oʻrganiladi va reja yoʻl-yoʻlakay oʻzgartiriladi; hammasini oldindan rejalashtirib qoʻyish oʻrniga.","also":["Agile development","agile ish usullari","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesti","text":"2001-yilda dasturchilar yozgan qisqa bayonot. U ogʻir rejalar va qogʻozbozlikdan koʻra odamlarni, ishlaydigan natijalarni, mijozlar bilan yaqin ishlashni va oʻzgarishlarga javob berishni birinchi oʻringa qoʻyadi.","also":["Manifesto for Agile Software Development","Agile manifesto"]},{"id":"waterfall","g":"agile","word":"Waterfall (sharshara usuli)","text":"Eskiroq ish usuli: avval hamma narsa rejalashtiriladi, keyin hammasi quriladi, keyin hammasi sinaladi, bosqichma-bosqich. Kechroq oʻzgartirish qiyin va qimmat.","also":["waterfall model","sharshara modeli"]},{"id":"iteration","g":"agile","word":"Iteratsiya","text":"Biror narsani qurish, tekshirish va yaxshilashning bitta davri. Agile ish shunday davrlar zanjiri, sprint esa ularning bir turi.","also":["iteratsiyalar","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Sprint yoki ish davrida mahsulotga qoʻshilgan, avvalgisiga mos tushadigan yangi ishlaydigan qism.","also":["inkrementlar","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Mashhur Agile ish usuli: kichik jamoa maqsad sari qisqa sprintlarda ishlaydi, aniq rollar va rejalashtirish, tekshirish, yaxshilash uchun bir nechta muntazam uchrashuvlar bilan."},{"id":"scrumteam","g":"agile","word":"Scrum jamoasi","text":"Scrumʼda ishni bajaradigan kichik guruh: mahsulot egasi, Scrum Master va dasturchilar.","also":["Scrum jamoalari","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum tadbirlari","text":"Scrumʼdagi muntazam uchrashuvlar: sprint rejalashtirish, kundalik scrum, sprint tahlili va retro. Koʻpchilik ularni «marosimlar» (ceremonies) deydi.","also":["ceremonies","Scrum ceremonies","Scrum marosimlari"]},{"id":"sprintplan","g":"agile","word":"Sprint rejalashtirish","text":"Sprint boshidagi uchrashuv: jamoa sprint nega muhimligi, qaysi kartalarni olishi va qanday boshlashi haqida kelishadi.","also":["planning meeting","rejalashtirish uchrashuvi"]},{"id":"sprintgoal","g":"agile","word":"Sprint maqsadi","text":"Sprint nima uchun ekanini aytadigan bitta gap. Maqsadga erishilsa, mayda vazifalar yoʻl-yoʻlakay oʻzgarishi mumkin.","also":["sprint maqsadlari","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlogi","text":"Joriy sprint uchun tanlangan kartalar va jamoaning ularni bajarish rejasi.","also":["sprint backlogs","sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Mahsulot backlogi","text":"Mahsulot uchun qurilishi mumkin boʻlgan hamma narsaning toʻliq, tartiblangan roʻyxati, eng muhimi tepada. U oʻrganganingiz sari oʻzgarib turadi.","also":["mahsulot backloglari","product backlogs"]},{"id":"productgoal","g":"agile","word":"Mahsulot maqsadi","text":"Mahsulot intilayotgan kattaroq natija; u jamoaga keyin nima qilishni tanlashga yordam beradi.","also":["mahsulot maqsadlari","product goals"]},{"id":"refinement","g":"agile","word":"Backlogni takomillashtirish","text":"Kartalar tayyor boʻlishi uchun backlogni muntazam koʻrib chiqish: tartibga solish, boʻlish, tartiblash va tafsilot qoʻshish. Backlog grooming deb ham ataladi.","also":["backlog grooming","refinement","backlogni tartibga solish"]},{"id":"sprintreview","g":"agile","word":"Sprint tahlili","text":"Sprint oxiridagi uchrashuv: jamoa nima bitirganini koʻrsatadi, odamlarning fikrini eshitadi va keyingi qadamni hal qiladi.","also":["sprint reviews","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Tayyor ishni uni soʻragan odamlarga jonli, ishlayotgan holda koʻrsatish.","also":["demolar","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Vaqt chegarasi (timebox)","text":"Biror ish uchun belgilangan aniq vaqt. U tugagach, hammasi bitmagan boʻlsa ham, toʻxtaysiz.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Tezlik (velocity)","text":"Jamoa odatda bir sprintda qancha ish bitirishi; keyingi safar qancha olishni rejalashtirish uchun ishlatiladi. Bu odamlar qanchalik qattiq ishlayotganining bahosi emas.","also":["team velocity","jamoa tezligi"]},{"id":"capacity","g":"agile","word":"Sigʻim (capacity)","text":"Taʼtillar va boshqa ishlarni hisobga olgandan keyin jamoa bir davrda qancha ish ola olishi.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown grafigi","text":"Sprintda qolgan ishning kundan-kunga kamayib borishini koʻrsatadigan grafik. Chiziq tekis qolsa, biror narsa tiqilib qolgan.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup grafigi","text":"Bitgan ishning vaqt oʻtishi bilan oshib borishini, rejalashtirilgan umumiy hajm yonida koʻrsatadigan grafik, shunda qachon yetib borishingiz koʻrinadi.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban doskasi","text":"Doskaning oʻzi: ishning har bir bosqichi uchun ustun, kartalar ular boʻylab oʻtadi.","also":["Kanban doskalari","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Tortish tizimi (pull system)","text":"Yangi ish faqat kimdir uni olishga imkoni boʻlganda boshlanadigan ish usuli; allaqachon band odamga ish yuklanmaydi.","also":["pull-based","pull system"]},{"id":"flow","g":"agile","word":"Oqim (flow)","text":"Ish doska boʻylab qanchalik silliq oʻtishi. Yaxshi oqim kartalar toʻplanib qolmay, harakatda ekanini bildiradi.","also":["flow of work","ish oqimi"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (bajarilish muddati)","text":"Kimdir biror narsani soʻragandan to u tugatilgunicha qancha vaqt oʻtishi.","also":["lead times","bajarilish muddati"]},{"id":"cycletime","g":"agile","word":"Cycle time (sikl vaqti)","text":"Karta ustida ish haqiqatan boshlanganidan to tugaguncha qancha vaqt ketishi.","also":["cycle times","sikl vaqti"]},{"id":"throughput","g":"agile","word":"Oʻtkazuvchanlik (throughput)","text":"Haftada yoki istalgan belgilangan vaqtda nechta karta tugatilishi.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Tiqilinch (bottleneck)","text":"Ish toʻplanib, orqasidagi hamma narsani sekinlashtiradigan yagona bosqich, shisha boʻynining torligiga oʻxshab.","also":["bottlenecks","tiqilinchlar"]},{"id":"swimlane","g":"agile","word":"Qatorli yoʻlak (swimlane)","text":"Doska boʻylab bir turdagi kartalarni, masalan shoshilinch ishlarni yoki bitta jamoa kartalarini guruhlaydigan qator.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Isrofni (mijozga foyda bermaydigan hamma narsani) qisqartiradigan va ishni oqimda ushlab turadigan ish usuli."},{"id":"waste","g":"agile","word":"Isrof","text":"Leanʼda kuch sarflatadigan, lekin mijozga foyda bermaydigan har qanday narsa, masalan kutish, qayta ishlash yoki hech kim foydalanmaydigan narsalarni qurish.","noTip":1},{"id":"kaizen","g":"agile","word":"Doimiy takomillashtirish","text":"Kichik muntazam oʻzgarishlar bilan doim bir oz yaxshilanib borish, keyin ular foyda berganini tekshirish. Retrolar buning bir yoʻli. Kaizen deb ham ataladi.","also":["kaizen","uzluksiz yaxshilash"]},{"id":"selforg","g":"agile","word":"Oʻzini oʻzi tashkil qiluvchi jamoa","text":"Ishni qanday qilishni unga qadam-baqadam aytib turishlarini kutmay, oʻzi hal qiladigan jamoa.","also":["self-organising","self-managing team","oʻzini oʻzi boshqaradigan jamoa"]},{"id":"crossfunc","g":"agile","word":"Koʻp funksiyali jamoa","text":"Ishni oʻzi tugatish uchun kerakli barcha mahoratlarga, masalan dizayn, qurish va sinashga ega jamoa.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Haqiqiy ishga kirishishdan oldin savolga javob topish uchun qisqa, vaqti cheklangan tadqiqot.","also":["spikes"]},{"id":"rework","g":"agile","word":"Qayta ishlash","text":"Ish birinchi marta toʻgʻri chiqmagani uchun uni qaytadan qilish.","also":["reworked","rework"]},{"id":"safe","g":"agile","word":"Kengaytirilgan Agile (SAFe)","text":"Agileʼni katta tashkilotdagi koʻplab jamoalarda qoʻllash usullari. SAFe (Scaled Agile Framework) — mashhur namunalardan biri.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Loyihaning kod papkasi va commitlarning toʻliq tarixi. U kompyuteringizda, GitHubʼda yoki ikkalasida ham turishi mumkin.","also":["repozitoriy"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda alohida ish chizigʻi, shunda asosiy versiyaga tegmasdan oʻzgartirishlar kiritish mumkin.","also":["branchlar"]},{"id":"commit","g":"build","word":"Commit","text":"Kodning nima oʻzgargani haqida qisqa izoh bilan saqlangan nusxasi. Unga doim qaytish mumkin.","also":["commitlar"]},{"id":"push","g":"build","word":"Push","text":"Saqlangan nusxalaringizni (commitlarni) shu kompyuterdan internetdagi umumiy nusxaga, masalan GitHubʼga yuborish, shunda ular zaxiralanadi va boshqalar ularni ola oladi."},{"id":"merge","g":"build","word":"Merge","text":"Bir branchdagi oʻzgarishlarni boshqasiga, odatda asosiy versiyaga qaytarib qoʻshish."},{"id":"pr","g":"build","word":"Pull request","text":"Branchdagi oʻzgarishlarni tekshirib, asosiy versiyaga qoʻshishni soʻrash. Baʼzi saytlar buni merge request deydi.","also":["PR","PRs","merge request","pull request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodning vazifasini oʻzgartirmasdan tartibga solish: kichikroq fayllar, aniqroq nomlar, kamroq takrorlash."},{"id":"bug","g":"build","word":"Bug","text":"Ishlashi kerak boʻlganidek ishlamayotgan narsa.","also":["buglar"]},{"id":"peerreview","g":"build","word":"Hamkasblar tekshiruvi","text":"Ikkinchi juft koʻz: ish sizga yetib kelishidan oldin muallifdan boshqa kimdir uni tekshiradi, shunda kamroq xato oʻtib ketadi. AI-gileʼda har bir kartani boshqa AI tekshiradi.","also":["kod tekshiruvi","peer review","code review"]},{"id":"code","g":"build","word":"Kod","text":"Kompyuterga nima qilishni aytadigan yozma koʻrsatmalar. Manba kodi (source code) deb ham ataladi.","also":["source code","manba kodi"],"noTip":1},{"id":"proglang","g":"build","word":"Dasturlash tili","text":"Kod yozish uchun til, masalan JavaScript, Python yoki Java. Har xil ishlarga har xil tillar mos keladi.","also":["dasturlash tillari","programming languages"]},{"id":"developer","g":"build","word":"Dasturchi (dev)","text":"Kod yozadigan va oʻzgartiradigan odam. Programmer yoki software engineer deb ham ataladi.","also":["developer","developers","programmer","programmers","software engineer","dasturchilar"]},{"id":"software","g":"build","word":"Dasturiy taʼminot","text":"Kompyuter va telefonlarda ishlaydigan dasturlar, mashinalarning oʻzidan (apparat taʼminotidan) farqli oʻlaroq.","noTip":1},{"id":"app","g":"build","word":"Ilova (app)","text":"Application soʻzining qisqartmasi: odamlar telefonda, kompyuterda yoki veb-brauzerda biror ish bitirish uchun foydalanadigan dastur.","also":["apps","application","applications","ilovalar"],"noTip":1},{"id":"webapp","g":"build","word":"Veb-ilova","text":"Veb-brauzerda ishlaydigan ilova, shuning uchun oʻrnatadigan narsa yoʻq.","also":["web apps","web application","veb-ilovalar"]},{"id":"frontend","g":"build","word":"Front end (old qism)","text":"Ilovaning koʻrib bosadigan qismi: ekranlar, tugmalar va soʻzlar, koʻpincha brauzeringizda.","also":["front-end","frontend","old qism"]},{"id":"backend","g":"build","word":"Back end (orqa qism)","text":"Ilovaning parda ortidagi qismi: maʼlumotlarni saqlaydi va biror narsani bosganingizda ishni bajaradi, masalan parolingizni tekshiradi.","also":["back-end","backend","orqa qism"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Ham front end (old qism), ham back end (orqa qism) ustida ishlash.","also":["full-stack"]},{"id":"ui","g":"build","word":"Foydalanuvchi interfeysi (UI)","text":"Odam ekranda koʻrib, foydalanadigan narsa: joylashuv, tugmalar, menyular va matn.","also":["UI","user interface","interfeys"]},{"id":"ux","g":"build","word":"Foydalanuvchi tajribasi (UX)","text":"Biror narsadan foydalanish qanday his qilinishi: oson, aniq va yoqimli yoki chalkash va sekin.","also":["UX","user experience","foydalanish tajribasi"]},{"id":"accessibility","g":"build","word":"Qulaylik (a11y)","text":"Narsalarni hamma, jumladan yaxshi koʻrmaydiganlar, sichqoncha ishlatolmaydiganlar yoki ekran oʻqiydigan dasturdan foydalanadiganlar ham ishlata oladigan qilish.","also":["a11y","accessibility","imkoniyati cheklanganlar uchun qulaylik"]},{"id":"responsive","g":"build","word":"Moslashuvchan dizayn","text":"Sahifalarni telefondan katta monitorgacha har qanday ekran oʻlchamiga sigʻadigan va yaxshi ishlaydigan qilish.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Dizayn tizimi","text":"Ranglar, shriftlar, tugmalar va qoidalarning umumiy toʻplami, shunda har bir ekran bir xil koʻrinadi va bir xil ishlaydi.","also":["dizayn tizimlari","design systems"]},{"id":"architecture","g":"build","word":"Arxitektura","text":"Tizimning umumiy tuzilishi: asosiy qismlari nimalar va ular bir-biri bilan qanday gaplashadi."},{"id":"database","g":"build","word":"Maʼlumotlar bazasi (DB)","text":"Axborotning tartibli omborxonasi, ilova oʻqiy va oʻzgartira oladigan juda kuchli elektron jadvalga oʻxshaydi.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Baza sxemasi","text":"Bazaning tuzilishi: unda axborotning qaysi jadvallari bor va har biriga nima kiradi.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Structured query language qisqartmasi: koʻplab bazalardan axborot soʻrash yoki uni oʻzgartirish uchun ishlatiladigan til.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Maʼlumot","text":"Kompyuter saqlaydigan axborot, masalan ismlar, buyurtmalar yoki sozlamalar.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Doim yoniq turadigan va boshqa kompyuterlarning soʻrovlariga javob beradigan kompyuter, masalan sahifaga kirganingizda uni sizga yuboradi.","also":["serverlar","servers"]},{"id":"client","g":"build","word":"Klient (mijoz dasturi)","text":"Biror narsani soʻraydigan tomon, odatda serverga murojaat qiladigan brauzer yoki ilovangiz. Biznesda esa bu soʻz shunchaki mijozni anglatadi.","also":["clients","klient"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Application programming interface qisqartmasi: bir dastur boshqasiga yubora oladigan soʻrovlarning tayyor menyusi, masalan ob-havo xizmatidan bugungi prognozni soʻrash.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (murojaat manzili)","text":"API menyusining bitta bandi: dastur biror narsani olish yoki yuborish uchun murojaat qiladigan veb-manzil.","also":["endpoints","endpoint"]},{"id":"integration","g":"build","word":"Integratsiya","text":"Ikki tizimni birga ishlashi uchun ulash, masalan doʻkoningiz buyurtmalarni hisob dasturingizga yuborishi.","also":["integrations","integratsiyalar"]},{"id":"webhook","g":"build","word":"Webhook","text":"Bir tizim boshqasiga biror narsa roʻy bergan zahoti oʻzi yuboradigan xabar, masalan «toʻlov qabul qilindi».","also":["webhooks","vebhuk"]},{"id":"library","g":"build","word":"Kutubxona (library)","text":"Boshqa birov yozgan tayyor kod, uni oʻzingiz yozmasdan qayta ishlatishingiz mumkin.","also":["libraries","kutubxonalar"],"noTip":1},{"id":"framework","g":"build","word":"Framework (ish asosi)","text":"Ilova qurish uchun tayyor tuzilma; kod qanday joylashishining koʻp qismini u hal qiladi, toʻldirib chiqadigan uy karkasiga oʻxshaydi.","also":["frameworks","freymvork"]},{"id":"sdk","g":"build","word":"Dasturiy taʼminot yaratish toʻplami (SDK)","text":"Bitta platforma yoki xizmat uchun dastur yaratishga moʻljallangan vositalar, kod va namunalar qutisi.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Dasturiy bogʻliqlik","text":"Kodingiz ishlashi uchun kerak boʻlgan kutubxona yoki vosita. Ularni yangilab turish xavfsizlik uchun muhim.","also":["software dependencies","software dependency"]},{"id":"package","g":"build","word":"Paket","text":"Loyihaga oʻrnatib ishlatish mumkin boʻlgan tayyor kod toʻplami.","also":["packages","paketlar"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Paket menejeri","text":"Kodingiz bogʻliq boʻlgan paketlarni olib keladigan va yangilaydigan vosita. npm — keng tarqalgan biri.","also":["package managers","npm","paket menejerlari"]},{"id":"git","g":"build","word":"Git","text":"Kod oʻzgarishlari tarixini commitlar va branchlar koʻrinishida saqlash uchun eng keng qoʻllaniladigan vosita."},{"id":"github","g":"build","word":"GitHub","text":"Git repolarini internetda saqlaydigan sayt, shunda jamoalar kod ulashishi, oʻzgarishlarni koʻrib chiqishi va ishni kuzatishi mumkin."},{"id":"vcs","g":"build","word":"Versiyalarni boshqarish","text":"Fayllardagi har bir oʻzgarishning toʻliq tarixini saqlash, shunda kim nimani oʻzgartirganini koʻrish va kerak boʻlsa orqaga qaytish mumkin. Git shuni qiladi.","also":["source control","version control system","version control"]},{"id":"clone","g":"build","word":"Klonlash (clone)","text":"Reponing oʻz tarixi bilan birga toʻliq nusxasini kompyuteringizda yaratish.","also":["cloned","cloning","clone"]},{"id":"pull","g":"build","word":"Pull (tortib olish)","text":"Umumiy nusxadan (masalan GitHubʼdan) eng yangi commitlarni kompyuteringizga olib kelish. Pushʼning teskarisi.","also":["git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Asosiy branch","text":"Hamma ishlaydigan kodning rasmiy versiyasi, koʻpincha main yoki master deb ataladi.","also":["master branch","main branch"]},{"id":"conflict","g":"build","word":"Birlashtirish ziddiyati (merge conflict)","text":"Ikki oʻzgarish bir xil qatorlarga turlicha tegsa, kompyuter ularni birlashtira olmaydi va tanlovni odam qilishi kerak boʻladi.","also":["merge conflicts","merge conflict"]},{"id":"diff","g":"build","word":"Diff (farq)","text":"Ikki versiya orasida aynan nima oʻzgarganini koʻrsatadigan koʻrinish: qoʻshilgan va olib tashlangan qatorlar.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Birovning reposidan oʻzingiz uchun olingan nusxa; uni oʻzgartirsangiz ham, asl repoga taʼsir qilmaydi.","also":["forks","forked","fork qilish"]},{"id":"script","g":"build","word":"Skript","text":"Bitta ishni oʻzi bajaradigan qisqa dastur, masalan fayllarni tartibga solish yoki ilovani ishga tushirish.","also":["scripts","script","skriptlar"],"noTip":1},{"id":"build","g":"build","word":"Build (yigʻish)","text":"Kodni ishga tayyor narsaga aylantirish yoki shu ishga tayyor natijaning oʻzi.","also":["builds","build"],"noTip":1},{"id":"compile","g":"build","word":"Kompilyatsiya","text":"Odamlar yozgan kodni kompyuter bevosita ishga tushira oladigan shaklga tarjima qilish.","also":["compiler","compile","kompilyator"]},{"id":"cli","g":"build","word":"Buyruq qatori (CLI)","text":"Bosish oʻrniga kompyuterga koʻrsatmalarni yozib beradigan matnli oyna. Terminal deb ham ataladi.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Konfiguratsiya (config)","text":"Dastur qanday ishlashini boshqaradigan sozlamalar; ular kodda emas, alohida saqlanadi, shuning uchun oʻzgartirish oson.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Muhit oʻzgaruvchisi","text":"Dastur ishga tushganda unga beriladigan sozlama, koʻpincha manzillar yoki parollar uchun, shunda ular kodga yozib qoʻyilmaydi.","also":["environment variables","env var","environment variable"]},{"id":"debugging","g":"build","word":"Xatolarni tuzatish (debugging)","text":"Nima uchun biror narsa ishlamayotganini topish va uni tuzatish.","also":["debug","debugged","debugging","debag"]},{"id":"pairing","g":"build","word":"Juftlikda dasturlash","text":"Ikki odam (yoki odam va AI) bir kod ustida birga ishlaydi: biri yozadi, biri tekshiradi.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Hujjatlar (docs)","text":"Biror narsa qanday ishlashi yoki undan qanday foydalanish haqida yozma izohlar.","also":["documentation","docs","hujjatlashtirish"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Repoda birinchi oʻqiladigan fayl: loyiha nima va uni qanday ishga tushirish.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Eskirgan tizim (legacy)","text":"Hali ham ishlatilayotgan, lekin oʻzgartirish qiyin boʻlgan eski tizim, koʻpincha uni tushunadigan odam kam qolgani uchun.","also":["legacy systems","legacy code","legacy system"]},{"id":"techdebt","g":"build","word":"Texnik qarz","text":"Hozir vaqtni tejaydigan, lekin keyingi oʻzgarishlarni sekinlashtiradigan yoʻl-yoʻlakay yechimlar, foizi oshib boradigan qarzga oʻxshaydi. Refaktoring uni uzadi.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Biror narsa kerakli tarzda ishlashini tekshirish. Baʼzi testlarni kompyuter kod har oʻzgarganda oʻzi bajaradi; boshqalarida tayyor kartani qabul qilishdan oldin siz oʻzingiz sinab koʻrasiz.","also":["testlar"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Quality assurance qisqartmasi: ish jonli ishga tushishidan oldin toʻgʻriligiga ishonch hosil qilish uchun qilinadigan hamma narsa. AI-gileʼda bu avtomatik tekshiruvlar: QA qizil boʻlsa, nimadir oʻtmagan va u tuzatilmaguncha jonli ishga tusha olmaydi.","also":["sifat nazorati","sifat tekshiruvlari","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"Test toʻplami","text":"Siz sinab koʻrishingizni kutayotgan tayyor kartalar, birin-ketin. Birini qabul qiling yoki izoh bilan qaytaring, keyingisi chiqadi.","also":["test toʻplamlari","test pile","test piles"]},{"id":"autotest","g":"test","word":"Avtomatik test","text":"Kod har oʻzgarganda kompyuter oʻzi bajaradigan tekshiruv, xatolarni erta ushlash uchun.","also":["automated tests","automatic tests","avtomatik testlar"]},{"id":"manualtest","g":"test","word":"Qoʻlda test","text":"Ish kerakli tarzda ishlayotganini koʻrish uchun odamning uni qoʻlda sinab koʻrishi.","also":["manual tests","manual testing","qoʻlda sinash"]},{"id":"unittest","g":"test","word":"Unit test","text":"Kodning bitta mayda qismini yakka oʻzini tekshiradigan kichik avtomatik tekshiruv.","also":["unit tests","birlik testi"]},{"id":"integtest","g":"test","word":"Integratsiya testi","text":"Bir nechta qism faqat alohida emas, birgalikda ham toʻgʻri ishlashini tekshirish.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"Boshidan oxirigacha test (E2E)","text":"Haqiqiy foydalanuvchi kabi boshidan oxirigacha harakat qiladigan test, masalan roʻyxatdan oʻtish, sotib olish va toʻlash.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Foydalanuvchi qabul sinovi (UAT)","text":"Ishni soʻragan odamlar uni oʻzlari sinab koʻradi va u ularga kerakli ishni bajaryaptimi-yoʻqmi, aytadi. AI-gileʼdagi sinov toʻplami shuning oʻziga xos koʻrinishi.","also":["UAT","acceptance testing","qabul sinovi"]},{"id":"regression","g":"test","word":"Regressiya","text":"Ilgari ishlagan, lekin oʻzgarishdan keyin buzilib qolgan narsa. Regressiya testlari eski narsalar hamon ishlashini tekshiradi.","also":["regressions","regression test","regression tests","regression testing","regression"]},{"id":"smoke","g":"test","word":"Smoke test (tezkor tekshiruv)","text":"Asosiy narsalar umuman ishlayotganini juda tez tekshirish, masalan oʻzgarish ishga tushgan zahoti. Oʻtmasa, toʻxtang va sababini koʻrib chiqing.","also":["smoke tests","smoke test"]},{"id":"exploratory","g":"test","word":"Tadqiqot testi","text":"Mahsulotni erkin sinab, turli yoʻllar bilan turtib koʻrish, rejalashtirilgan tekshiruvlar qoldirib ketadigan muammolarni topish uchun.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Test holati","text":"Sinab koʻriladigan bitta yozilgan holat: qadamlar va nima boʻlishi kerakligi.","also":["test cases","test case"]},{"id":"coverage","g":"test","word":"Test qamrovi","text":"Kodning qancha qismi avtomatik testlar bilan tekshirilishi. Koʻproq odatda xavfsizroq, lekin yuqori qamrovning oʻzi yaxshi ishlashini isbotlamaydi.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test maʼlumotlari","text":"Sinov paytida ishlatiladigan oʻylab topilgan namuna axborot, shunda hech bir haqiqiy odamning shaxsiy maʼlumotlari ochilib qolmaydi.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Chekka holat (edge case)","text":"Chegaradagi odatiy boʻlmagan vaziyat, masalan boʻsh forma yoki tutuq belgisi bor ism; bunday joylarda koʻpincha narsalar buziladi.","also":["edge cases","chekka holatlar"]},{"id":"happypath","g":"test","word":"Baxtli yoʻl (happy path)","text":"Hammasi toʻgʻri ketadigan odatiy yoʻl. Yaxshi sinov baxtsiz yoʻllarni ham sinab koʻradi."},{"id":"perftest","g":"test","word":"Unumdorlik testi","text":"Biror narsa qanchalik tez ishlashini va yuk ostida qanchalik yaxshi bardosh berishini tekshirish.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Yuklama testi","text":"Koʻp odam bir vaqtda foydalanganda tizim qanday bardosh berishini tekshirish.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Xavfsizlik testi","text":"Tizimdagi zaif joylarni qidirish: ular orqali kimdir tizimni suiisteʼmol qilishi yoki koʻrmasligi kerak boʻlgan narsani koʻrishi mumkin.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Qulaylik testi","text":"Turli imkoniyatli odamlar, jumladan ekran oʻqiydigan dastur bilan yoki faqat klaviatura bilan mahsulotdan foydalana olishini tekshirish.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"Koddagi ehtimoliy xatolar va tartibsiz uslubni topadigan avtomatik tekshiruv, dasturlar uchun imlo tekshirgichga oʻxshaydi.","also":["linter","lint","linter"]},{"id":"static","g":"test","word":"Statik tahlil","text":"Kodni ishga tushirmasdan, avtomatik oʻqib muammolarni tekshirish.","also":["static code analysis","static analysis"]},{"id":"flaky","g":"test","word":"Beqaror test (flaky test)","text":"Baʼzan oʻtadigan, baʼzan aniq sababsiz oʻtmay qoladigan test, shuning uchun unga toʻliq ishonib boʻlmaydi.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Xatoni takrorlash (repro)","text":"Xatoni oʻsha qadamlarni takrorlab, ataylab yana yuzaga keltirish, shunda uni oʻrganish va tuzatish mumkin boʻladi. Bu qadamlarni yozib qoʻyish xato haqidagi xabarning eng foydali qismi.","also":["repro","reproduce","steps to reproduce","takrorlash qadamlari"]},{"id":"severity","g":"test","word":"Jiddiylik darajasi","text":"Muammo taʼsiri qanchalik yomonligi: kichik bezovtalikdan tortib hamma narsa toʻxtashigacha.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Dasturning yangi versiyasini uni ishlatadigan kompyuterlarga, masalan sinov nusxasi yoki jonli xizmatga koʻchirish."},{"id":"release","g":"change","word":"Reliz","text":"Birga efirga chiqadigan, nomi bor tayyor ishlar toʻplami, nima oʻzgargani haqida qisqa yozuvlar bilan. 🚀 Relizlar bu yozuvlarni bajarilgan kartalardan yozadi.","also":["relizlar","release","releases"]},{"id":"rollback","g":"change","word":"Orqaga qaytarish","text":"Yangi versiya muammo keltirganda oxirgi ishlagan versiyaga qaytish. AI-gileʼda Roll back har bir oʻzgarishda yozilgan bekor qilish qadamlarini bitta roʻyxatga yigʻadi.","also":["orqaga qaytarildi","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Efirda","text":"Odamlar foydalanadigan haqiqiy versiya, sinab koʻrish uchun nusxadan farqli oʻlaroq. U yerga qoʻyishni efirga chiqish deymiz. Dasturchilar buni production ham deyishadi.","also":["efirga chiqish","prodakshn","live","production"],"noTip":1},{"id":"change","g":"change","word":"Oʻzgarish","text":"Odamlar tayanadigan narsaga rejalashtirilgan, oldindan yozib qoʻyilgan oʻzgarish: nima, nega, xavf, qachon va qanday bekor qilish. «🔀 Oʻzgarish soʻrash» bilan boshlang.","also":["oʻzgarishlar","oʻzgarish soʻrovi","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Xavf","text":"Notoʻgʻri ketishi mumkin boʻlgan narsa, qanchalik ehtimolli va qanchalik yomon boʻlishiga qarab baholangan. ⚠️ Xavflar ularni bitta roʻyxatda saqlaydi, eng yuqori baho tepada, har birida qayta koʻrish sanasi bor.","also":["xavflar","risk","xavflar reyestri","risks","risk register"]},{"id":"chgwin","g":"change","word":"Oʻzgarish oynasi","text":"Oʻzgarishlar efirga chiqishi mumkin boʻlgan vaqtlar, masalan, tinch seshanba oqshomi. Oynadan tashqarida oʻzgarish kartasini yakunlab boʻlmaydi, agar u favqulodda holat boʻlmasa.","also":["oʻzgarish oynalari","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Oʻzgarish jonli ishga tushishidan oldingi oxirgi tekshiruv: tasdiqlashi kerak boʻlgan har bir kishi Go yoki No go deydi. Hamma Go desagina davom etadi.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Tasdiqlash","text":"Ish boshlanishidan oldin «ha»ni kutish. Doʻstingiz ochgan karta yoki oʻzgarish ✅ Tasdiqlashlar boʻlimida siz uni tasdiqlaguningizcha yoki rad etguningizcha kutadi.","also":["tasdiqlashlar","approval","approvals"]},{"id":"quiettime","g":"change","word":"Sokin vaqt","text":"Hech narsa jonli ishga tushmaydigan vaqt oraligʻi, masalan jonli efir, demo paytida yoki tunda. Jamoalar ishlash va sinashda davom etadi, lekin jonli ishga tushirish u tugaguncha kutadi. Boshqa joylarda uni change freeze deyishadi.","also":["sokin vaqtlar","oʻzgarishlarni muzlatish","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Dasturni yaratadigan va uni ishlatib turadigan odamlar koʻp avtomatlashtirish yordamida bitta jamoa boʻlib ishlaydigan usul; shunda oʻzgarishlar tez-tez va xavfsiz ishga tushadi."},{"id":"cicd","g":"change","word":"CI/CD (uzluksiz integratsiya va yetkazib berish)","text":"Hammaning oʻzgarishlari tez-tez asosiy versiyaga birlashtiriladi va har safar avtomatik tekshiriladi (uzluksiz integratsiya), shuning uchun dastur doim bitta tugma bosilishi bilan ishga tushishga tayyor (uzluksiz yetkazib berish).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Uzluksiz joylashtirish","text":"Uzluksiz yetkazib berishdan bir qadam nariga: tekshiruvlardan oʻtgan har bir oʻzgarish oʻzi ishga tushadi, bosiladigan tugma yoʻq.","also":["continuous deployments","continuous deployment"]},{"id":"pipeline","g":"change","word":"Pipeline (quvur)","text":"Oʻzgarish ishga tushish yoʻlida oʻtadigan avtomatik qadamlar ketma-ketligi: yigʻish, sinash, keyin joylashtirish.","also":["pipelines","pipeline"]},{"id":"environment","g":"change","word":"Muhit (environment)","text":"Tizimning bitta maqsad uchun alohida nusxasi, masalan biri ishlab chiqish uchun, biri sinash uchun va biri jonli tizim.","also":["environments","muhitlar"],"noTip":1},{"id":"devenv","g":"change","word":"Ishlab chiqish muhiti","text":"Dasturchi ishlaydigan nusxa, koʻpincha oʻz kompyuterida, bu yerda biror narsani buzish hech kimga zarar qilmaydi.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"Test muhiti","text":"Faqat sinash uchun ishlatiladigan tizimning alohida nusxasi, shunda haqiqiy xizmatga tegilmaydi.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Staging (yakuniy sinov muhiti)","text":"Jonli tizimdek sozlangan oxirgi nusxa, oʻzgarish ishga tushishidan oldingi yakuniy tekshiruv uchun.","also":["staging environment","staging"]},{"id":"artifact","g":"change","word":"Build artefakti","text":"Build natijasida hosil boʻladigan fayl yoki toʻplam, saqlashga, tekshirishga yoki ishga tushirishga tayyor.","also":["build artifacts","build artifact","artefakt"]},{"id":"hotfix","g":"change","word":"Hotfix (shoshilinch tuzatish)","text":"Muhim narsa buzilgani uchun odatdagi rejadan tashqari tezda ishga tushiriladigan shoshilinch tuzatish.","also":["hotfixes","hotfix"]},{"id":"patch","g":"change","word":"Patch (yamoq)","text":"Xatoni tuzatadigan yoki xavfsizlik teshigini yopadigan kichik yangilanish. Xavfsizlik yamoqlarini tezda oʻrnatish muhim.","also":["patches","security patch","security patches","patch","yamoq"]},{"id":"version","g":"change","word":"Versiya raqami","text":"2.4.1 kabi yorliq, qaysi relizga ega ekaningizni aytadi. Koʻpincha birinchi raqam katta oʻzgarishlarda, oxirgisi esa kichik tuzatishlarda oʻzgaradi.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Reliz yozuvlari (release notes)","text":"Relizda nimalar oʻzgarganining foydalanuvchilar uchun qisqa, oddiy roʻyxati, tuzatishlar va maʼlum cheklovlar bilan. Changelog deb ham ataladi.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Feature flag (imkoniyat kaliti)","text":"Imkoniyat uchun yoqish-oʻchirish kaliti: yangi ish yashirin holda ishga tushib, yangi reliz chiqarmasdan yoqilishi (yoki yana oʻchirilishi) mumkin.","also":["feature flags","feature toggle","feature toggles","feature flag"]},{"id":"rollfwd","g":"change","word":"Oldinga yurish (roll forward)","text":"Yomon relizni eskisiga qaytish oʻrniga, tezda yangi, tuzatilgan versiyani chiqarib tuzatish.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Canary reliz","text":"Oʻzgarishni avval kichik guruh uchun ishga tushirish, hammaga esa u yaxshi koʻringandan keyingina. Nomi konchilar ogohlantirish uchun yer ostiga olib tushgan kanareykalardan olingan.","also":["canary releases","canary","canary release"]},{"id":"bluegreen","g":"change","word":"Blue-green joylashtirish","text":"Jonli tizimning ikki nusxasini saqlab, odamlarni yangisiga bir yoʻla oʻtkazish; shunda yomon ketsa darhol qaytish mumkin.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Toʻxtovsiz joylashtirish","text":"Yangi versiyani xizmat foydalanuvchilar uchun hech toʻxtamasdan ishga tushirish.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Oʻzgarishlarni boshqarish","text":"Oʻzgarishlar muvaffaqiyatli chiqishiga yordam berish: xavfni baholash, kerakli tasdiqni olish va yaxshi vaqtni tanlash. Change management deb ham ataladi.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Oʻzgarishlar kengashi (CAB)","text":"Muhim oʻzgarishlarni koʻrib chiqib, ularga ruxsat berish-bermaslik va qachon berishni kelishadigan guruh.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standart oʻzgarish","text":"Har safar bir xil, sinalgan usulda bajariladigan past xavfli oʻzgarish, shuning uchun oldindan tasdiqlangan.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Oddiy oʻzgarish","text":"Amalga oshirilishidan oldin tekshirilishi va tasdiqlanishi kerak boʻlgan oʻzgarish.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Favqulodda oʻzgarish","text":"Jiddiy muammoni tuzatish yoki oldini olish uchun darhol bajarilishi kerak boʻlgan oʻzgarish, mos ravishda tezroq tasdiqlanadi.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Avtomatlashtirish","text":"Takrorlanadigan ishni kompyuterga oʻzi bajartirish, shunda u tezroq va har safar bir xil bajariladi.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Infratuzilma","text":"Dastur ishlaydigan mashinalar, tarmoqlar va xizmatlar.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Kod koʻrinishidagi infratuzilma (IaC)","text":"Serverlaringiz va sozlamalaringizni kod bilan birga saqlanadigan fayllarda tasvirlash, shunda ularni har safar aynan bir xil tarzda qayta qurish mumkin.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Bulut","text":"Mashinalarga oʻzingiz egalik qilish oʻrniga, kompyuterlar, xotira va xizmatlarni internet orqali yirik taʼminotchidan ijaraga olish.","also":["the cloud","cloud computing","cloud","bulutli hisoblash"]},{"id":"provider","g":"change","word":"Bulut taʼminotchisi","text":"Hisoblash quvvatini internet orqali ijaraga beradigan kompaniya, masalan Amazon Web Services (AWS), Microsoft Azure yoki Google Cloud.","also":["cloud providers","cloud provider"]},{"id":"hosting","g":"change","word":"Xosting","text":"Ilovangiz yoki saytingiz odamlar yetib borishi uchun yashaydigan va ishlaydigan joy; odatda kompaniyadan ijaraga olinadi.","also":["hosting"]},{"id":"domain","g":"change","word":"Domen nomi","text":"Odamlar yozadigan veb-manzil, masalan example.com. Uni yilma-yil ijaraga olasiz, shuning uchun yangilab turish kerak.","also":["domain names","domain","domen"]},{"id":"dns","g":"change","word":"DNS","text":"Domain name system qisqartmasi: internetning manzil kitobi; example.com kabi nomni toʻgʻri kompyuter manziliga aylantiradi.","also":["domain name system"]},{"id":"container","g":"change","word":"Konteyner","text":"Ilovani va unga kerak hamma narsani oʻz ichiga olgan yopiq paket, shuning uchun u har qanday kompyuterda bir xil ishlaydi. Docker eng mashhur vosita.","also":["containers","Docker","container"],"noTip":1},{"id":"vm","g":"change","word":"Virtual mashina (VM)","text":"Haqiqiy kompyuter ichida ishlaydigan dasturiy «kompyuter», shunda bitta katta mashina koʻplab mashina vazifasini bajara oladi.","also":["VM","VMs","virtual machines","virtual machine"]},{"id":"serverless","g":"change","word":"Serversiz (serverless)","text":"Hech qanday serverga oʻzingiz qaramasdan kod ishlatish: taʼminotchi kerak boʻlganda uni ishga tushiradi, siz esa foydalangan narsangiz uchun toʻlaysiz."},{"id":"lb","g":"change","word":"Yuk taqsimlagich (load balancer)","text":"Tashrif buyuruvchilarni bir nechta serverga taqsimlaydigan narsa, shunda birortasi ortiqcha yuklanib ketmaydi.","also":["load balancers","load balancer"]},{"id":"cache","g":"change","word":"Kesh (cache)","text":"Yaqinda olingan natijalarning yaqin joyda saqlanadigan qulay ombori, shunda bir xil narsani qayta olib kelish yoki hisoblash shart emas. Uni tozalash eskirgandek koʻringan sahifalarni tuzatishi mumkin.","also":["caches","caching","cached","cache"]},{"id":"cdn","g":"change","word":"Kontent yetkazish tarmogʻi (CDN)","text":"Sahifalaringiz va rasmlaringiz nusxalarini tashrif buyuruvchilarga yaqin joyda saqlaydigan butun dunyo boʻylab serverlar toʻplami, shunda ular tez yuklanadi.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migratsiya (koʻchirish)","text":"Maʼlumot yoki tizimlarni eski joydan yangisiga koʻchirish yoki bazaning tuzilishini ehtiyotkorlik bilan oʻzgartirish.","also":["migrations","database migration","migration"]},{"id":"service","g":"run","word":"Xizmat","text":"Siz yaratgan va odamlar tayanadigan narsa, masalan, sayt yoki ilova, u ishlab turishi uchun qarab boriladi. «Bu loyiha xizmat» belgisini qoʻying va u nima taklif qilishi, undan kim foydalanishi va kim navbatchi ekanini yozing.","also":["xizmatlar","servis","service","services"]},{"id":"uptimepct","g":"run","word":"Uptime (ishlash vaqti)","text":"Xizmat vaqtning qancha qismida ishlab turishi, odatda foizda. 99,9% bilan ham oyiga taxminan 43 daqiqa ishlamay qolishi mumkin.","also":["uptime percentage","uptime"]},{"id":"uptime","g":"run","word":"Ishlashni tekshirish","text":"Har bir necha daqiqada xizmatingiz hali ham javob berayotganini avtomatik tekshirish. Agar u ketma-ket bir necha marta oʻtmasa, AI-gile oʻzi hodisa kartasini ochadi.","also":["uptime checks","ishlash tekshiruvlari"]},{"id":"statuspage","g":"run","word":"Holat sahifasi","text":"Xizmat ishlayaptimi yoki yoʻqmi (yashil, toʻq sariq yoki qizil) oxirgi yangilanish bilan koʻrsatadigan ochiq sahifa, shunda foydalanuvchilar soʻramasdan oʻzlari tekshira oladi.","also":["holat sahifalari","status page","status pages"]},{"id":"desk","g":"run","word":"Yordam stoli","text":"Xizmatingizdan foydalanadigan odamlarning savollari va xabarlari keladigan joy. AI-gile har birini soʻrov, hodisa yoki gʻoyaga ajratadi va agar u allaqachon xabar qilingan narsaga oʻxshasa, buni aytadi.","also":["yordam stollari","xizmat stoli","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Xizmat soʻrovi","text":"Kimdir nimadir buzilganini xabar qilish oʻrniga oddiy narsa soʻrayapti, masalan yangi akkaunt yoki ozgina yordam. U oʻz navbatini kutadi; hodisa birinchi oʻtadi.","also":["xizmat soʻrovlari","soʻrov","service request","service requests"]},{"id":"incident","g":"run","word":"Hodisa","text":"Hozir uni ishlatayotgan odamlar uchun buzilgan yoki toʻgʻri ishlamayotgan narsa, masalan veb-sayt ishlamayotgani yoki juda sekinligi. 🔥 hodisa kartasi navbatsiz oʻtadi: uni qayta ishlatib yuborish birinchi oʻrinda.","also":["hodisalar","insident","incident","incidents"]},{"id":"major","g":"run","word":"Katta hodisa","text":"Katta hodisa: koʻp odam zarar koʻrgan yoki pul yo maʼlumotlar xavf ostida. Bitta tugma barcha jamoalarni unga qoʻyadi (toʻda), kim navbatchi boʻlsa uygʻotadi va har 30 daqiqada holat yangilanishini soʻraydi.","also":["katta hodisalar","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Navbatchilik","text":"Nimadir buzilganda, hatto tunda ham, javob beradigan odam boʻlish. Har bir xizmatning navbatchi jamoa aʼzosi bor, uning hodisalari uchun birinchi boʻlib u uygʻotiladi.","also":["navbatchi","on call","on-call"]},{"id":"replyby","g":"run","word":"Javob berish muddati","text":"Karta birinchi javobni qancha kutishi mumkin, masalan, hodisa uchun bir soat. Shundan keyin unda qizil soat paydo boʻladi, hech narsa jimgina unutilib ketmasin. Buni response target ham deyishadi.","also":["javob muddati","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Hodisa tahlili","text":"Hodisadan keyin qisqa ortga nazar: nima boʻldi, nima yordam berdi va nimani oʻzgartirish kerak, hech kimni ayblamasdan. Usiz hodisani yopib boʻlmaydi. Buni post-mortem ham deyishadi.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Muammo","text":"Bir yoki bir nechta hodisa ortidagi yashirin sabab. 🧩 muammo kartasi qayta-qayta takrorlanadigan hodisalarni jamlaydi, shunda sabab topiladi va butunlay tuzatiladi.","also":["muammolar","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Asosiy sabab","text":"Biror narsa buzilishining haqiqiy sababi, siz koʻrgan nosozlikning oʻzi emas. Asosiy sababni tuzating, shunda hodisa qaytib kelmaydi.","also":["asosiy sabablar","ildiz sabab","root cause","root causes"]},{"id":"workaround","g":"run","word":"Vaqtinchalik yechim","text":"Haqiqiy tuzatish tayyor boʻlguncha ishni davom ettirish yoʻli, masalan, biror narsa qotib qolsa, uni qayta ishga tushirish. U muammo kartasiga yoziladi, shunda hech kim uni qaytadan oʻylab topishi shart emas.","also":["vaqtinchalik yechimlar","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Maʼlum xato","text":"Sababi tushunilgan, lekin hali tuzatilmagan muammo; odatda vaqtinchalik yechimi yozib qoʻyiladi. 🧩 Maʼlum xatolar ularni roʻyxatga oladi, shunda hamma qaytadan qidirib oʻtirmay, vaqtinchalik yechimdan foydalanadi.","also":["maʼlum xatolar","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Maʼlum turdagi nosozlikni tuzatish uchun qadamma-qadam yoʻriqnoma, shunda u har safar bir xil va tez bajariladi. Katta hodisadan keyin jamoa sizga tasdiqlash uchun runbook taklif qilishi mumkin.","also":["runbooks","qadamma-qadam yoʻriqnoma"]},{"id":"ci","g":"run","word":"Konfiguratsiya elementi","text":"Xizmatingiz tayanadigan bitta narsa: server, domen, sertifikat, kalit yoki yetkazib beruvchi kabi. 🗂️ Elementlar ularni har bir xizmat boʻyicha koʻrsatadi, shunda hodisa nimaga taʼsir qilishini va nimani yangilash yoki zaxiralash kerakligini koʻrasiz.","also":["konfiguratsiya elementlari","elementlar","configuration item","configuration items"]},{"id":"expiry","g":"run","word":"Amal qilish muddati","text":"Yangilanmasa ishlashdan toʻxtaydigan narsaning sanasi, masalan veb-saytning xavfsizlik sertifikati yoki veb-manzili. AI-gile bu sanalarni kuzatadi va har birini yangilash uchun 30 kun oldin bitta karta yaratadi, shunda hech narsa kutilmaganda toʻxtab qolmaydi.","also":["amal qilish muddatlari","muddat tugashi","muddat kuzatuvi","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"Zaxira nusxa","text":"Maʼlumotlaringizning avvalroq saqlangan nusxasi, biror narsa yoʻqolsa yoki buzilsa, unga tayanish uchun. AI-gile har kuni doskalaringizning zaxira nusxasini oladi.","also":["zaxira nusxalar","bekap","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Tiklash","text":"Maʼlumotlarni zaxira nusxadan qaytarish. Zaxira nusxa uni tiklash mumkinligini bilgandagina haqiqatan hisobga kiradi, shuning uchun vaqti-vaqti bilan sinab koʻrgan maʼqul.","also":["tiklandi","restore","restored"]},{"id":"svcreview","g":"run","word":"Xizmat sharhi","text":"Xizmatning bir oyiga ortga nazar: ochilgan va tuzatilgan hodisalar, odamlar qanchalik tez javob olgani, ishlash vaqti va sarflangan tokenlar. Oylik sharh buni har bir xizmat uchun koʻrsatadi.","also":["xizmat sharhlari","oylik sharh","oylik sharhlar","service review","monthly review"]},{"id":"accessreview","g":"run","word":"Kirish tekshiruvi","text":"Har 90 kunda kimlar hamon kira olishini tekshirish: ulashish havolalari, doʻstlarning rollari, saqlangan parollar va kalitlar. Har birini saqlaysiz yoki olib tashlaysiz, shunda eski kirish huquqlari qolib ketmaydi.","also":["kirish tekshiruvlari","access review","access reviews"]},{"id":"improvements","g":"run","word":"Yaxshilanishlar roʻyxati","text":"Jamoa yaxshilashga qaror qilgan hamma narsa bir joyda: retro takliflari, sharh harakatlari va muammo tuzatishlari, har biri oʻz holati bilan. Uni 📈 Yaxshilanishlar boʻlimidan toping.","also":["yaxshilanishlar roʻyxatlari","yaxshilanishlar","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Token chegarasi","text":"Xizmat agentlari sarflashi mumkin boʻlgan tokenlarning oylik chegarasi. 80% da ogohlantirish olasiz; 100% da ularning fon ishi keyingi oygacha yoki siz chegarani oshirguningizcha kutadi.","also":["token chegaralari","oylik token chegarasi","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Xizmatni boshqarish","text":"Xizmatni unga tayanadigan odamlar uchun kundan-kunga foydali va ishlab turadigan holda saqlashga tegishli hamma narsa.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Xizmatni yaxshi boshqarish boʻyicha keng qoʻllaniladigan qoʻllanma; hodisalar, muammolar va oʻzgarishlar kabi narsalarni qamrab oladi. Nomi bir vaqtlar IT Infrastructure Library degani edi."},{"id":"itsm","g":"run","word":"IT xizmatlarini boshqarish (ITSM)","text":"Texnologiyani odamlar uchun xizmat sifatida yuritish; soʻrovlar, hodisalar, oʻzgarishlar va yaxshilashlar bilan ishlashning aniq usullari bilan.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Boshqariladigan xizmat","text":"Sizning oʻrningizga boshqa birov yuritadigan va qarab turadigan xizmat; qanchalik yaxshi ishlashi kerakligi haqidagi kelishuv asosida.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Xizmat egasi","text":"Xizmat uchun yaxlit javob beradigan odam: u qanchalik yaxshi ishlashi, qancha turishi va qanday yaxshilanishi uchun.","also":["service owners","service owner"]},{"id":"sla","g":"run","word":"Xizmat darajasi kelishuvi (SLA)","text":"Mijozlarga xizmat qanchalik yaxshi ishlashi haqidagi yozma vaʼda, masalan «99,9% vaqt ishlab turadi» yoki «bir soat ichida javob beriladi»; buzilsa, koʻpincha pul qaytariladi.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Xizmat darajasi maqsadi (SLO)","text":"Xizmat bir davr mobaynida qanchalik yaxshi ishlashi kerakligi haqida jamoaning oʻz nishoni; ehtiyot uchun odatda SLAʼdan sal qattiqroq qoʻyiladi.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Xizmat darajasi koʻrsatkichi (SLI)","text":"Nishon bilan solishtirib tekshiradigan haqiqiy oʻlchov, masalan yaxshi yuklangan tashriflar ulushi.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Foydalanish mumkinligi (availability)","text":"Odamlar xizmatdan kerak boʻlganda foydalana oladimi-yoʻqmi; koʻpincha uptime bilan oʻlchanadi.","also":["high availability","availability"]},{"id":"downtime","g":"run","word":"Toʻxtab qolish vaqti (downtime)","text":"Xizmat ishlamayotgan yoki oʻchirib qoʻyilgan vaqt, rejalashtirilgan yoki yoʻq.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Xato byudjeti","text":"Ishonchlilik nishoningiz ruxsat beradigan kichik miqdordagi nosozlik. U qolgan ekan, oʻzgarishlarda tavakkal qilishingiz mumkin; tugagach, sekinlashasiz.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Uzilish","text":"Xizmat foydalanuvchilar uchun ishlamay qolgan yoki qattiq buzilgan vaqt.","also":["outages","outage"]},{"id":"degraded","g":"run","word":"Sifati pasaygan","text":"Ishlayapti, lekin yomon: sekin yoki baʼzi qismlari ishlamayapti.","also":["degraded service","degraded"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Xizmatni doim avtomatik kuzatib turish, shunda muammolar aniqlanadi, iloji boricha foydalanuvchilar sezmasidan oldin.","also":["monitoring"]},{"id":"observability","g":"run","word":"Observability (kuzatuvchanlik)","text":"Tizim ichida nima boʻlayotganini tashqaridan, uning loglari, raqamlari va izlari orqali qanchalik yaxshi bilish mumkinligi.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Log (jurnal)","text":"Dastur nima qilayotgani haqida yuritadigan kundalik; nima xato ketganini aniqlash uchun ishlatiladi.","also":["logs","logging","log"],"noTip":1},{"id":"trace","g":"run","word":"Trace (iz)","text":"Bitta soʻrov tizimning turli qismlaridan qadam-baqadam qanday oʻtishining yozuvi; qayerda sekinlashganini koʻrsatadi.","also":["traces","tracing","trace"]},{"id":"latency","g":"run","word":"Kechikish (latency)","text":"Biror narsa javob berishi qancha vaqt olishi, masalan bosish bilan sahifa paydo boʻlishi orasidagi kutish.","also":["latency"]},{"id":"alert","g":"run","word":"Ogohlantirish (alert)","text":"Biror narsaga eʼtibor kerakligi haqidagi avtomatik xabar, masalan veb-sayt javob bermayotgani.","also":["alerts","alerting","alert"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Ogohlantirishdan charchash","text":"Ogohlantirishlar shunchalik koʻpki, odamlar ularga, jumladan muhimlariga ham eʼtibor bermay qoʻyadi.","also":["alarm fatigue","alert fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard (boshqaruv paneli)","text":"Eng muhim raqamlar va holatlarni bir qarashda koʻrsatadigan ekran.","also":["dashboards","dashboard"],"noTip":1},{"id":"paging","g":"run","word":"Chaqirish (paging)","text":"Navbatchi odamga muammo haqida shoshilinch qoʻngʻiroq qilish yoki uni uygʻotish.","also":["paged","paging"]},{"id":"escalation","g":"run","word":"Yuqoriga uzatish (escalation)","text":"Masala joriy darajada yoki yetarlicha tez hal boʻlmasa, mahorati yoki vakolati kattaroq odamni jalb qilish.","also":["escalate","escalated","escalation"]},{"id":"triage","g":"run","word":"Triaj (saralash)","text":"Kelayotgan masalalarni shoshilinchligi va muhimligi boʻyicha tez saralash, shunda eng yomoni birinchi hal qilinadi.","also":["triaged","triage"]},{"id":"impact","g":"run","word":"Taʼsir","text":"Biror narsa odamlarga qanchalik taʼsir qilishi: nechtasiga va qanchalik qattiq.","noTip":1},{"id":"urgency","g":"run","word":"Shoshilinchlik","text":"Biror narsa qanchalik tez hal qilinishi kerakligi. Taʼsir va shoshilinchlik birgalikda ustuvorlikni belgilaydi.","noTip":1},{"id":"plevels","g":"run","word":"Ustuvorlik darajalari (P1, P2…)","text":"Masala qanchalik shoshilinchligini bildiruvchi yorliqlar. P1 eng jiddiy va darhol harakat talab qiladi.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Tiketlar navbati","text":"Olinishini kutayotgan soʻrovlar va hodisalar roʻyxati.","also":["ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Birinchi va ikkinchi liniya","text":"Yordam darajalari: birinchi liniya qoʻngʻiroqni qabul qilib, oddiy narsalarni tuzatadi; ikkinchi liniyada qiyinroq masalalar uchun chuqurroq mahorat bor. Tier 1 va tier 2 deb ham ataladi.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Hodisa qoʻmondoni","text":"Hodisaga javobni boshqaradigan yagona odam, shunda hamma kim qaror qilishini va kim nima qilishini biladi.","also":["incident commanders","incident commander"]},{"id":"responsetime","g":"run","word":"Javob vaqti","text":"Kimdir soʻrov yoki hodisani birinchi marta qoʻlga olguncha qancha vaqt oʻtishi.","also":["response times","response time"]},{"id":"resolution","g":"run","word":"Hal qilish vaqti","text":"Soʻrov yoki hodisani toʻliq hal qilishga, xabar berilganidan tuzatilgunicha qancha vaqt ketishi.","also":["resolution times","time to resolve","resolution time"]},{"id":"mttr","g":"run","word":"Oʻrtacha tiklanish vaqti (MTTR)","text":"Xizmat buzilgandan keyin uni yana ishlatib yuborish oʻrtacha qancha vaqt olishi. MTTR biroz boshqacha maʼnolarni bildirishi mumkin, shuning uchun nimani oʻlchayotganingizni ayting.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Nosozliklar orasidagi oʻrtacha vaqt (MTBF)","text":"Biror narsa buzilguncha xizmat oʻrtacha qancha vaqt ishlashi.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfiguratsiya maʼlumotlar bazasi (CMDB)","text":"Barcha konfiguratsiya elementlaringiz va ular qanday bogʻlanishi roʻyxati, shunda nima nimaga bogʻliqligini koʻrasiz.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aktiv (asset)","text":"Xizmatni yuritish uchun egalik qiladigan yoki pul toʻlaydigan qimmatli narsa, masalan noutbuk, dastur litsenziyasi yoki domen.","also":["assets","asset","aktivlar"],"noTip":1},{"id":"capplan","g":"run","word":"Quvvatni rejalashtirish","text":"Kelayotgan narsa uchun kompyuter quvvati, xotira va odamlar yetarli boʻlishiga ishonch hosil qilish.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Masshtablash","text":"Koʻproq foydalanuvchiga bardosh berish: mashinaga koʻproq quvvat berish (scaling up) yoki koʻproq mashina qoʻshish (scaling out).","also":["scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Biznesning uzluksizligi","text":"Katta nosozlik yuz berganda, masalan ofis, asosiy yetkazib beruvchi yoki kompyuterlar yoʻqolganda, muhim narsalarni davom ettirish rejalari.","also":["business continuity plan","business continuity"]},{"id":"dr","g":"run","word":"Falokatdan keyin tiklanish (DR)","text":"Jiddiy voqeadan, masalan butun maʼlumotlar markazi yoʻqolishidan keyin xizmatni qaytarish uchun reja va vositalar.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Tiklanish vaqti maqsadi (RTO)","text":"Falokatdan keyin xizmat qayta ishlashi shart boʻlguncha toʻxtab turishi mumkin boʻlgan eng uzoq vaqt.","also":["RTO"]},{"id":"rpo","g":"run","word":"Tiklanish nuqtasi maqsadi (RPO)","text":"Eng soʻnggi maʼlumotlardan qanchasini yoʻqotsangiz ham boʻlishi, vaqt bilan oʻlchanadi. Bir soatlik RPO kamida har soatda zaxira nusxa olish degani.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Zaxiralash (redundancy)","text":"Zaxira tayyor turishi, masalan ikkinchi server, shunda bitta nosozlik xizmatni toʻxtatmaydi.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover (zaxiraga oʻtish)","text":"Odatdagi tizim ishdan chiqqanda oʻzi zaxira tizimga oʻtib ketish.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Yagona nosozlik nuqtasi","text":"Zaxirasi boʻlmagani uchun buzilganda hammasini oʻzi bilan olib ketadigan bitta qism.","also":["single points of failure","SPOF","single point of failure"]},{"id":"maintwin","g":"run","word":"Texnik xizmat oynasi","text":"Xizmat taʼmirlash uchun toʻxtatilishi yoki sekinlashishi mumkin boʻlgan rejalashtirilgan vaqt; foydalanuvchilarga oldindan eʼlon qilinadi.","also":["maintenance windows","planned maintenance","maintenance window"]},{"id":"handover","g":"run","word":"Topshirish (handover)","text":"Ish, bilim va masʼuliyatni boshqa odam yoki jamoaga uzatish, shunda hech narsa tushib qolmaydi.","also":["handovers","handover"]},{"id":"kb","g":"run","word":"Bilimlar bazasi","text":"Foydalanuvchilar va jamoa uchun yordam maqolalari va javoblar toʻplami.","also":["knowledge bases","knowledge base"]},{"id":"csat","g":"run","word":"Mijozlar mamnunligi (CSAT)","text":"Foydalanuvchilar qanchalik mamnun boʻlganini bildiradigan ball; koʻpincha soʻrov yopilgandan keyin soʻraladi.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Yetkazib beruvchi","text":"Siz tayanadigan tashqi kompaniya, masalan xosting taʼminotchingiz. Vendor yoki uchinchi tomon deb ham ataladi.","also":["suppliers","vendor","vendors","third party","supplier"],"noTip":1},{"id":"retire","g":"run","word":"Xizmatni toʻxtatish","text":"Xizmatni butunlay va xavfsiz oʻchirish: foydalanuvchilarga xabar berish, uning maʼlumotlari va kirish huquqlarini hal qilish va xarajatlarini toʻxtatish.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"Qoʻllab-quvvatlash muddati tugashi (EOL)","text":"Mahsulot yaratuvchisidan yangilanish yoki yordam olishni toʻxtatgan vaqt; shuning uchun uni almashtirish kerak.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Kiberxavfsizlik","text":"Tizim va maʼlumotlarni buzib kirishdan, oʻgʻirlanishdan yoki shikastlanishdan himoya qilish.","also":["cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Autentifikatsiya","text":"Kimdir kimligini tekshirish, odatda parol yoki kod bilan. Koʻpincha authn deb qisqartiriladi.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Avtorizatsiya","text":"Kim ekanini bilganingizdan keyin, unga nima qilishga ruxsat borligini tekshirish. Koʻpincha authz deb qisqartiriladi.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Koʻp omilli autentifikatsiya (MFA)","text":"Ikki yoki undan koʻp isbot bilan kirish, masalan parol va telefondagi kod. Ikki omilli autentifikatsiya (2FA) deb ham ataladi.","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Yagona kirish (SSO)","text":"Bir marta kirib, koʻplab tizimlarga kirish, masalan ish akkauntingizdan hamma joyda foydalanish.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Parol menejeri","text":"Mustahkam parollar yaratib, ularni siz uchun eslab qoladigan ilova.","also":["password managers","password manager"]},{"id":"secret","g":"sec","word":"Sir (secret)","text":"Dastur biror narsaga kirish uchun ishlatadigan parol, kalit yoki boshqa maxfiy kod. U hech qachon ulashilmasligi yoki kodga yozilmasligi kerak.","also":["secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"API kaliti","text":"Dasturga boshqa xizmatning APIʼsidan foydalanishga imkon beradigan maxfiy kod; kim foydalanayotganini (va pulini toʻlayotganini) koʻrsatadi.","also":["API keys","API key"]},{"id":"accesstoken","g":"sec","word":"Kirish tokeni","text":"Dastur kirishga ruxsati borligini isbotlaydigan vaqtinchalik ruxsatnoma, shuning uchun har safar parolingiz kerak boʻlmaydi. AI tokeni bilan bir narsa emas.","also":["access tokens","access token"]},{"id":"encryption","g":"sec","word":"Shifrlash","text":"Axborotni chalkashtirib yuborish, shunda uni faqat toʻgʻri kalit egasi oʻqiy oladi.","also":["encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Veb-sahifalar xavfsiz yuboriladigan usul; brauzeringizdagi qulf belgisi bilan koʻrsatiladi, shunda oraliqdagi hech kim ularni oʻqiy yoki oʻzgartira olmaydi."},{"id":"cert","g":"sec","word":"SSL/TLS sertifikati","text":"Veb-sayt kimligini isbotlab, HTTPSʼdan foydalanishiga imkon beradigan raqamli guvohnoma. Muddati tugaydi, shuning uchun yangilab turish kerak.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikat"]},{"id":"permissions","g":"sec","word":"Ruxsatlar","text":"Kim nimani koʻrishi yoki oʻzgartirishi mumkinligi haqidagi qoidalar.","also":["permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Eng kam huquq tamoyili","text":"Har bir odam yoki dasturga faqat haqiqatan kerak boʻlgan kirish huquqini, faqat kerak boʻlgan vaqtga berish.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Rol asosidagi kirish nazorati (RBAC)","text":"Kirishni odamma-odam emas, rol boʻyicha, masalan koʻruvchi yoki tahrirlovchi sifatida berish.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Zaiflik","text":"Kimdir buzib kirish yoki zarar yetkazish uchun foydalanishi mumkin boʻlgan kamchilik.","also":["vulnerabilities","vulnerability","zaifliklar"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Yaratuvchilar uni tuzatishga hali hech qanday vaqt topmasidan oldin hujumchilar biladigan zaiflik.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Zararli dastur (malware)","text":"Zarar yetkazish, josuslik qilish yoki oʻgʻirlash uchun yaratilgan zararli dasturlar, masalan viruslar.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware (tovlamachi virus)","text":"Fayllaringizni qulflab, ochish uchun pul talab qiladigan zararli dastur. Yaxshi zaxira nusxalar eng yaxshi himoya.","also":["ransomware attack","ransomware"]},{"id":"phishing","g":"sec","word":"Fishing (phishing)","text":"Sizni parol yoki pulingizni berishga yoki zararli narsani ochishga aldashga urinadigan soxta xabarlar.","also":["phishing email","phishing emails","phishing","fishing"]},{"id":"socialeng","g":"sec","word":"Ijtimoiy muhandislik","text":"Kompyuterlarni emas, odamlarni aldab kirish huquqini olish, masalan «IT yordam xizmati»dan soxta qoʻngʻiroq."},{"id":"firewall","g":"sec","word":"Brandmauer (firewall)","text":"Qaysi tarmoq trafigi kirishi yoki chiqishi mumkinligini hal qiladigan qorovul.","also":["firewalls","firewall","fayrvol"]},{"id":"vpn","g":"sec","word":"VPN","text":"Virtual private network qisqartmasi: internet orqali yopiq, shifrlangan aloqa; koʻpincha ish tizimlariga xavfsiz kirish uchun ishlatiladi.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Xizmat koʻrsatishni rad etish hujumi (DoS, DDoS)","text":"Xizmatni shunchalik koʻp soxta trafik bilan toʻldirib tashlashki, haqiqiy odamlar undan foydalana olmay qoladi. DDoS esa hujum bir vaqtda koʻp kompyuterdan kelishini bildiradi.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetratsion test (pen test)","text":"Doʻstona mutaxassislarni buzib kirishga urinish uchun yollash, shunda zaifliklar haqiqiy hujumchilardan oldin topiladi.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Xavfsizlik auditi","text":"Biror narsa qanchalik himoyalanganini yaxshi amaliyotlar roʻyxatiga qarab ehtiyotkorlik bilan tekshirish.","also":["security audits","security audit"]},{"id":"threatmodel","g":"sec","word":"Tahdidlarni modellashtirish","text":"Biror narsaga kim, qanday hujum qilishi mumkinligi va uni toʻxtatish uchun nima qilishingiz haqida oldindan oʻylab chiqish.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Maʼlumotlar sizib chiqishi","text":"Shaxsiy axborot unga ega boʻlmasligi kerak boʻlgan odamlarga chiqib ketishi yoki ruxsatsiz yoʻqolishi yoxud oʻzgartirilishi.","also":["data breaches","data breach","maʼlumotlar buzilishi"]},{"id":"pii","g":"sec","word":"Shaxsiy maʼlumotlar","text":"Aniqlash mumkin boʻlgan odam haqidagi har qanday axborot, masalan ism, elektron pochta manzili yoki joylashuv. PII deb ham ataladi.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Shaxsiy maʼlumotlar haqidagi Yevropa qonuni (Buyuk Britaniyaning oʻz varianti bor): faqat kerakli narsani yigʻing, uni xavfsiz saqlang va odamlarga oʻz maʼlumotlarini koʻrish yoki oʻchirishga ruxsat bering.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Maʼlumotlarni himoya qilish","text":"Shaxsiy maʼlumotlarni toʻgʻri va qonun doirasida saqlash va ishlatish.","also":["data protection law","data protection"]},{"id":"privacypolicy","g":"sec","word":"Maxfiylik siyosati","text":"Qanday shaxsiy maʼlumot yigʻishingiz, nima uchun va u bilan nima qilishingizni aytadigan ochiq sahifa.","also":["privacy statement","privacy notice","privacy policy"]},{"id":"consent","g":"sec","word":"Rozilik","text":"Odamning maʼlumoti muayyan tarzda ishlatilishiga aniq, erkin «ha»si. U buni istalgan vaqt qaytarib olishi mumkin.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (kuki)","text":"Veb-sayt biror narsani, masalan tizimga kirganingizni eslab qolish uchun brauzeringizda saqlaydigan kichik fayl. Baʼzilari avval roziligingizni talab qiladi.","also":["cookies","cookie","kuki"],"noTip":1},{"id":"minimisation","g":"sec","word":"Maʼlumotni minimallashtirish","text":"Ish uchun haqiqatan kerak boʻlgan shaxsiy maʼlumotlarnigina yigʻish va saqlash.","also":["data minimization","data minimisation"]},{"id":"retention","g":"sec","word":"Maʼlumotni saqlash muddati","text":"Maʼlumot oʻchirilguncha qancha saqlanishi. Kerakli vaqtdan uzoq saqlamaslik xavfsizroq va koʻpincha qonun talabi.","also":["retention period","data retention"]},{"id":"anon","g":"sec","word":"Anonimlashtirish","text":"Maʼlumotni oʻzgartirish, shunda undan endi hech kimni oqilona aniqlab boʻlmaydi.","also":["anonymised","anonymization","anonymous data","anonymisation"]},{"id":"pseudo","g":"sec","word":"Psevdonimlashtirish","text":"Ismlar va boshqa tafsilotlarni kodlarga almashtirish; ularni qayta bogʻlash uchun kalit alohida saqlanadi. Bu hamon shaxsiy maʼlumot.","also":["pseudonymised","pseudonymization","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Maʼlumotlarni qayta ishlash shartnomasi (DPA)","text":"Yetkazib beruvchi sizning nomingizdan shaxsiy maʼlumotlar bilan qanday ishlashi mumkinligini aytadigan shartnoma.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Maʼlumotlarni himoya qilishga taʼsirni baholash (DPIA)","text":"Boshlashdan oldin shaxsiy maʼlumotlardan foydalanish rejasi odamlarga qanday taʼsir qilishi va xavflarni qanday kamaytirish haqida ehtiyotkorona oʻylab koʻrish.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit jurnali","text":"Kim, qachon nima qilganining yozuvi, shunda harakatlar keyinroq tekshirilishi mumkin.","also":["audit logs","audit trail","audit log"]},{"id":"compliance","g":"sec","word":"Qoidalarga muvofiqlik (compliance)","text":"Sizga tegishli qonunlar, qoidalar va standartlarga amal qilish hamda buni koʻrsata olish.","also":["compliant","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Axborot xavfsizligini boshqarish boʻyicha mashhur xalqaro standart. Kompaniyalar unga muvofiq sertifikatlanishi mumkin.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Tashqi auditorlar tekshirgan AQSH hisoboti; kompaniya mijozlar maʼlumotlarini toʻgʻri muhofaza qilishini koʻrsatadi.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Topshiriq ustida oʻzi ishlaydigan AI: kodni oʻqiydi, oʻzgartirishlar kiritadi, tekshiruvlarni ishga tushiradi va hisobot beradi. Uning ishi baribir tekshiriladi.","also":["agentlar"]},{"id":"token","g":"ai","word":"Token","text":"AI oʻqiydigan va yozadigan kichik matn boʻlaklari, har biri taxminan soʻzning toʻrtdan uch qismi. AI foydalanishi tokenlarda hisoblanadi, shuning uchun kamroq token rejangizdan koʻproq qoldiradi.","also":["tokenlar"]},{"id":"hook","g":"ai","word":"Hook","text":"Belgilangan paytda, masalan AI sessiyasi boshlanganda oʻzi ishga tushadigan kichik buyruq; shunda jamoa izohlaringizni eshitadi.","also":["hooklar"]},{"id":"ai","g":"ai","word":"Sunʼiy intellekt (AI)","text":"Biz odatda odam kerak deb hisoblaydigan ishlarni, masalan yozish, savollarga javob berish yoki rasmlarni tanishni bajaradigan kompyuter tizimlari.","also":["AI","artificial intelligence","sunʼiy intellekt"],"noTip":1},{"id":"ml","g":"ai","word":"Mashinali oʻqitish (ML)","text":"Kompyuterlarga aniq qoidalar berish oʻrniga, koʻp misollardan qonuniyatlarni oʻrgatish usuli.","also":["machine learning","ML"]},{"id":"model","g":"ai","word":"Model","text":"AI tizimining oʻqitilgan «miyasi»; juda koʻp misollardan oʻrganish orqali yaratiladi. Modellar mahorati, tezligi va narxi bilan farq qiladi.","also":["models","AI model","modellar"],"noTip":1},{"id":"llm","g":"ai","word":"Katta til modeli (LLM)","text":"Juda katta hajmdagi matn bilan oʻqitilgan AI modeli, shuning uchun u tilni oʻqiy va yoza oladi.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generativ AI","text":"Faqat saralash yoki aniqlash bilan cheklanmay, matn, rasm yoki kod kabi yangi narsalar yaratadigan AI.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Yozib yoki gapirib, kundalik tilda suhbatlashadigan dastur.","also":["chatbots","chatbot"]},{"id":"prompt","g":"ai","word":"Prompt (soʻrov)","text":"AIʼga beradigan narsangiz: savolingiz yoki koʻrsatmalaringiz, qoʻshib bergan narsalaringiz. Aniqroq prompt odatda yaxshiroq javob olib keladi.","also":["prompts","prompt"]},{"id":"prompteng","g":"ai","word":"Prompt muhandisligi","text":"Ishonchli, foydali natija beradigan promptlar yozish mahorati.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Tizim prompti","text":"Suhbat boshlanishidan oldin AIʼga beriladigan, uning roli va qoidalarini belgilaydigan fon koʻrsatmalar. Ular siz yozganingizdan ogʻirroq turadi.","also":["system prompts","system instruction","system instructions","system prompt"]},{"id":"context","g":"ai","word":"Kontekst","text":"AI ishlayotganda koʻra oladigan hamma narsa: koʻrsatmalar, xabarlaringiz, oʻqigan fayllari va oldingi javoblari.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekst oynasi","text":"AI bir vaqtda qancha narsani yodda tuta olishi, tokenlarda oʻlchanadi. Undan oshgach, eski qismlar tashlab yuboriladi yoki qisqa xulosaga aylantiriladi.","also":["context windows","context window"]},{"id":"session","g":"ai","word":"Sessiya","text":"AI bilan boshidan oxirigacha bitta ish suhbati. Yangi sessiya yangi xotira bilan boshlanadi.","also":["sessions","session","seans"],"noTip":1},{"id":"memory","g":"ai","word":"Xotira","text":"AI sessiyalar oraligʻida saqlaydigan qaydlar, shunda u xohishlaringizni va oldingi qarorlarni eslab qoladi.","noTip":1},{"id":"hallucination","g":"ai","word":"Gallyutsinatsiya","text":"AI oʻziga ishongandek gapirgan, lekin aslida toʻqilgan yoki xato narsa. Muhim faktlarni tekshiring.","also":["hallucinations","hallucinate","hallucinates","hallucination"]},{"id":"training","g":"ai","word":"Oʻqitish","text":"Modeldan hech kim foydalanmasdan oldin unga juda koʻp misol koʻrsatib oʻrgatish.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Oʻqitish maʼlumotlari","text":"Model oʻrgangan misollar. Uning bilimi oʻsha maʼlumotlar yigʻilgan sanada toʻxtaydi.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Bilimlar chegarasi sanasi","text":"AI ichki bilimi tugaydigan sana. Keyingi voqealarni, ularni qidirib topmasa, u bilmaydi.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning (nozik sozlash)","text":"Mavjud modelni oʻz misollaringiz bilan qoʻshimcha oʻqitish, uni bitta muayyan ishda kuchliroq qilish uchun.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Inferens (modelni ishlatish)","text":"AI modelining oʻqitilayotgan emas, balki biror narsaga javob berish uchun haqiqatan ishlatilishi.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Vositalardan foydalanish","text":"AI faqat gapirmasdan, ilova bergan vositalar orqali buyruq ishga tushirish, fayl oʻqish yoki internetdan qidirish kabi ishlarni qila olishi.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Subagent (yordamchi agent)","text":"Asosiy AI kichikroq ishni topshiradigan va undan natijani qaytarib oladigan yordamchi AI.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Koʻp agentli tizim","text":"Bir ish ustida birga ishlaydigan bir nechta AI; har birining oʻz qismi bor, kichik jamoaga oʻxshaydi.","also":["multi-agent system","multi-agent"]},{"id":"autonomy","g":"ai","word":"Mustaqillik (avtonomiya)","text":"AI odamdan soʻrashdan oldin oʻzi qancha ish qilishi mumkinligi.","also":["autonomous","autonomy","avtonomiya"]},{"id":"hitl","g":"ai","word":"Jarayondagi inson (human in the loop)","text":"AI qilgan ishni muhim nuqtalarda tekshirish yoki tasdiqlash uchun odamni jarayonda saqlash. AI-gileʼda bu siz.","also":["human-in-the-loop","HITL","human in the loop"]},{"id":"guardrails","g":"ai","word":"Himoya chegaralari (guardrails)","text":"AI harakatlarini xavfsiz saqlaydigan cheklovlar va tekshiruvlar, masalan hech narsa ishga tushishidan oldin tasdiq talab qilinishi. Ular xato xavfini kamaytiradi, lekin istisno qilmaydi.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"Qidiruv bilan boyitilgan generatsiya (RAG)","text":"AI javob berishdan oldin oʻz hujjatlaringizdan narsalarni qidirib koʻrishiga imkon berish, shunda uning javoblari sizning faktlaringizga tayanadi.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (maʼno vektori)","text":"Matnni uning maʼnosini ifodalaydigan raqamlar roʻyxatiga aylantirish, shunda kompyuter oʻxshash maʼnoli narsalarni topa oladi.","also":["embeddings","embedding"]},{"id":"vectordb","g":"ai","word":"Vektor bazasi","text":"Oʻsha raqamlar roʻyxatlarini (embeddinglarni) qidirish uchun yaratilgan baza; oʻxshash maʼnoli materialni topish uchun.","also":["vector databases","vector store","vector database"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Vositalar va maʼlumot manbalarini AI ilovalariga ulashning umumiy usuli, shunda AI ulardan foydalana oladi.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Harorat (temperature)","text":"AI javoblari qanchalik erkin va kutilmagan boʻlishini belgilaydigan sozlama. Past qiymat barqarorroq, oldindan bilsa boʻladigan javoblar beradi; yuqorisi esa xilma-xilroq javoblar. Hech biri uni har doim haq qilib qoʻymaydi.","also":["model temperature","temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Bir necha turdagi axborot, masalan matn, rasm va tovush bilan ishlay olish.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Baholash (eval)","text":"AI tanlangan misollarda qanchalik yaxshi ishlashining rejalashtirilgan sinovi, shunda modellar yoki promptlarni solishtirishingiz mumkin.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Tarafkashlik (bias)","text":"AI (yoki odam) nohaq tarzda bir tomonga ogʻishi; koʻpincha bu u nimadan oʻrganganiga bogʻliq boʻladi.","also":["biased","bias","xolislik yoʻqligi"],"noTip":1},{"id":"responsible","g":"ai","word":"Masʼuliyatli AI","text":"AIʼdan adolatli, xavfsiz va halol foydalanish; natijalar uchun hamon odamlar javobgar.","also":["ethical AI","responsible AI","axloqiy AI"]},{"id":"injection","g":"ai","word":"Prompt injection (yashirin koʻrsatma hujumi)","text":"Veb-sahifa yoki fayldagi yashirin koʻrsatmalar AIʼni foydalanuvchisi soʻramagan ishni qilishga undashga urinadigan hiyla.","also":["prompt injections","prompt injection"]},{"id":"ratelimit","g":"ai","word":"Soʻrovlar chegarasi (rate limit)","text":"Xizmatga belgilangan vaqt ichida yubora oladigan soʻrovlar soni chegarasi. Undan oshsangiz, kutishingiz kerak.","also":["rate limits","rate limited","rate limit"]},{"id":"usagelimit","g":"ai","word":"Foydalanish limiti","text":"Tarifingiz bir davrda qancha AI ishiga ruxsat berishi; undan keyin u toʻxtaydi yoki qimmatroq turadi.","also":["usage limits","usage limit"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Dasturni asosan AIʼga xohlaganingizni tasvirlab, kodni yozishni unga topshirish orqali yaratish.","also":["vibe-coding","vibe coding"]},{"id":"budget","g":"money","word":"Byudjet","text":"Biror narsa uchun ajratilgan pul miqdori.","also":["budgets","byudjet"],"noTip":1},{"id":"costest","g":"money","word":"Xarajat bahosi","text":"Boshlashdan oldin biror narsa qancha turishi haqidagi eng yaxshi taxmin.","also":["cost estimates","cost estimate"]},{"id":"roi","g":"money","word":"Investitsiya daromadi (ROI)","text":"Sarflaganingizga nisbatan qaytarib olganingiz. Musbat boʻlsa, arzigan.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Egalik qilishning umumiy qiymati (TCO)","text":"Biror narsaning butun umri davomida haqiqatda turadigan hamma narsasi, faqat sotib olish narxi emas: ishlatish, yordam, yangilash va oxirida undan voz kechish.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx va OpEx","text":"CapEx — saqlab qolinadigan narsalarga oldindan sarflanadigan pul; OpEx esa davomli xarajat, masalan oylik hisoblar.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Obuna","text":"Biror narsadan foydalanishda davom etish uchun muntazam, odatda oylik yoki yillik toʻlash.","also":["subscriptions","subscription","obunalar"],"noTip":1},{"id":"saas","g":"money","word":"Xizmat sifatidagi dastur (SaaS)","text":"Internetda foydalanadigan va obuna orqali toʻlaydigan dastur; uni yaratuvchi siz uchun yuritadi.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Ishlatganingizcha toʻlash","text":"Faqat ishlatganingiz uchun toʻlash, masalan bulutli hisoblash yoki AI tokenlari kabi.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Limitdan oshgan sarf","text":"Tarifingizga kiritilganidan ortiq foydalanish; buning uchun qoʻshimcha pul olinishi mumkin.","also":["overages","overage charges","overage"]},{"id":"billingalert","g":"money","word":"Hisob-kitob ogohlantirishi","text":"Sarf yoki foydalanish siz tanlagan darajaga yetganda keladigan xabar. U ogohlantiradi, lekin keyingi xarajatlarni har doim toʻxtatavermaydi.","also":["billing alerts","spending alert","billing alert"]},{"id":"freetier","g":"money","word":"Bepul daraja","text":"Pullik xizmatning cheklovlari bor bepul darajasi. Boshlash uchun qulay.","also":["free plan","free tier","bepul tarif"]},{"id":"pricing","g":"money","word":"Narx tarifi","text":"Xizmat sotadigan turli paketlar; har birining oʻz narxi va cheklovlari bor.","also":["pricing plans","price plan","pricing plan","tariflar"]},{"id":"licence","g":"money","word":"Litsenziya","text":"Boshqa birov yaratgan narsadan, masalan dasturdan, shriftlardan yoki rasmlardan qanday foydalanish, nusxalash, oʻzgartirish yoki ulashish mumkinligi haqidagi qoidalar.","also":["licences","license","licenses","licence"],"noTip":1},{"id":"opensource","g":"money","word":"Ochiq manbali dastur (open source)","text":"Kodini hamma oʻqiy oladigan, litsenziyasi qoidalari doirasida bepul ishlata oladigan va koʻpincha oʻzgartira oladigan dastur.","also":["open-source","open source software","OSS","open source"]},{"id":"osslicence","g":"money","word":"Ochiq manba litsenziyasi","text":"Ochiq manbali kod bilan keladigan qoidalar. Baʼzilari deyarli hamma narsaga ruxsat beradi (masalan MIT); baʼzilari oʻzgarishlaringizni ham ulashishni soʻraydi (masalan GPL).","also":["open source licences","MIT licence","GPL","open source licence"]},{"id":"proprietary","g":"money","word":"Yopiq (proprietary)","text":"Kompaniyaga tegishli va nusxalash yoki oʻzgartirish erkin boʻlmagan. Ochiq manbaning teskarisi.","also":["proprietary software","proprietary"]},{"id":"copyright","g":"money","word":"Mualliflik huquqi","text":"Yaratuvchining oʻz ishi, jumladan kod va yozuvlar nusxalarini nazorat qilish qonuniy huquqi.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Intellektual mulk (IP)","text":"Qonun egalik qilinadigan deb hisoblaydigan gʻoyalar va ijodlar, masalan kod, dizaynlar, nomlar va logotiplar.","also":["intellectual property","IP"]},{"id":"tos","g":"money","word":"Foydalanish shartlari","text":"Xizmatdan foydalanganingizda rozi boʻladigan qoidalar.","also":["terms and conditions","terms of use","terms of service"]},{"id":"contract","g":"money","word":"Shartnoma","text":"Ikki tomon orasidagi, qonun qoʻllab-quvvatlaydigan yozma kelishuv.","also":["contracts","contract","shartnomalar"],"noTip":1},{"id":"sow","g":"money","word":"Ish bayoni (SOW)","text":"Aynan qanday ish, qachongacha va qancha pulga bajarilishini belgilaydigan hujjat.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Qatʼiy narx","text":"Butun ish uchun kelishilgan narx, u qancha vaqt olishidan qatʼi nazar.","also":["fixed-price","fixed price"]},{"id":"tm","g":"money","word":"Vaqt va materiallar boʻyicha","text":"Belgilangan narx oʻrniga, haqiqatan ishlangan soatlar va ishlatilgan narsalar uchun toʻlash.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Hisob-faktura","text":"Bajarilgan ish yoki yetkazilgan tovar uchun toʻlovni soʻrovchi hisob.","also":["invoices","invoice","invoys"],"noTip":1},{"id":"lockin","g":"money","word":"Taʼminotchiga bogʻlanib qolish (vendor lock-in)","text":"Taʼminotchidan ketish shunchalik qiyin yoki qimmatki, unga bogʻlanib qolasiz.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Xaridlar (procurement)","text":"Yetkazib beruvchilarni tanlash va ulardan sotib olish jarayoni.","also":["procurement","xarid"]},{"id":"servicecredit","g":"money","word":"Xizmat krediti","text":"Yetkazib beruvchi SLAʼga rioya qilmaganda olinadigan qaytarilgan pul yoki chegirma.","also":["service credits","service credit"]}]}};
